package ios

import protocol "github.com/tliron/glsp/protocol_3_16"

type Keyword struct {
	Keyword       string
	Documentation string
	Insert        string
}

func NewKeyword(k string, d string, i string) Keyword {
	return Keyword{Keyword: k, Documentation: d, Insert: i}
}

func (k *Keyword) Completion() protocol.CompletionItem {
	kind := protocol.CompletionItemKindKeyword
	format := protocol.InsertTextFormatSnippet
	c := protocol.CompletionItem{
		Label: k.Keyword,
		Documentation: protocol.MarkupContent{
			Kind:  protocol.MarkupKindMarkdown,
			Value: k.Documentation,
		},
	}
	c.InsertText = &k.Insert
	c.Kind = &kind
	c.InsertTextFormat = &format
	return c
}

func Keywords() map[string]Keyword {
	k := make(map[string]Keyword)
	k["activation-character"] = NewKeyword("activation-character", "To define the character you ent er at a vacant terminal to begin a terminal session, use the activation-character command in line configuration mode. To make any character activate a terminal, use the no form of this command. Return (decimal 13) Line configuration (config-line) See the “ASCII Character Set and Hexadecimal Values” document for a list of ASCII characters.", "activation-character ascii-number no activation-character")
	k["alias"] = NewKeyword("alias", "To create a command alias, use the alias command in global configuration mode. To delete all aliases in a command mode or to delete a specific alias, and to revert to the original command syntax, use the no form of this command. A set of six basic EXEC mode aliases are enabled by default. See the “Usage Guidelines” section of this command for a list of default aliases. Global configuration You can use simple words or abbreviations as command aliases. The table below lists the basic EXEC mode aliases that are enabled by default. The default aliases in the table above are predefined. These default aliases can be disabled with the no alias exec command. Common keyword aliases (which cannot be disabled) include running-config (keyword alias for system:running-config ) and startup-config (keyword alias for nvram:startup-config ). See the description of the copy command for more information about these keyword aliases. Note that aliases can be configured for keywords instead of entire commands. You can create, for example, an alias for the first part of any command and still enter the additional keywords and arguments as normal. To determine the value for the mode argument, enter the command mode in which you would issue the original command (and in which you will issue the alias) and enter the ? command. The name of the command mode should appear at the top of the list of commands. For example, the second line in the following sample output shows the name of the command mode as “Interface configuration”: To match the name of the command mode to the acceptable mode keyword for the alias command, issue the alias ? command. As shown in the following sample output, the keyword needed to create a command alias for the access-expression command is interface : When you use online help, command aliases are indicated by an asterisk (*), and displayed in the following format: *command-alias \u003Doriginal-command For example, the lo command alias is shown here along with other EXEC mode commands that start with “lo”: When you use online help, aliases that contain multiple keyword elements separated by spaces are displayed in quotes, as shown here: To list only commands and omit aliases, begin your input line with a space. In the following example, the alias td is not shown, because there is a space before the t? command line. To circumvent command aliases, use a space before entering the command. In the following example, the command alias express is not recognized because a space is used before the command. As with commands, you can use online help to display the arguments and keywords that can follow a command alias. In the following example, the alias td is created to represent the command telnet device . The /debug and /line switches can be added to telnet device to modify the command: You must enter the complete syntax for the command alias. Partial syntax for aliases is not accepted. In the following example, the parser does not recognize the command t as indicating the alias td :", "alias mode command-alias original-command no alias mode [command-alias]")
	k["archive"] = NewKeyword("archive", "To enter archive configuration mode, use the archive command in global configuration mode. This command has no arguments or keywords. Archive configuration mode is not entered. Global configuration (config)", "archive")
	k["async-bootp"] = NewKeyword("async-bootp", "To configure extended BOOTP requests for asynchronous interfaces as defined in RFC 1084, use the async-bootp command in global configuration mode. To restore the default, use the no form of this command. If no extended BOOTP commands are entered, the Cisco IOS software generates a gateway and subnet mask appropriate for the local network. Global configuration Use the show async-bootp EXEC command to list the configured parameters. Use the no async-bootp command to clear the list.", "async-bootp tag [:hostname] data no async-bootp")
	k["autobaud"] = NewKeyword("autobaud", "To set the line for automatic baud rate detection (autobaud), use the autobaud command in line configuration mode. To disable automatic baud detection, use the no form of this command. This command has no arguments or keywords. Autobaud detection is disabled. Fixed speed of 9600 bps. Line configuration The autobaud detection supports a range from 300 to 19200 baud. A line set for autobaud cannot be used for outgoing connections, nor can you set autobaud capability on a line using 19200 baud when the parity bit is set (because of hardware limitations).", "autobaud no autobaud")
	k["auto-sync"] = NewKeyword("auto-sync", "To enable automatic synchronization of the configuration files in NVRAM, use the auto-sync command in main-cpu redundancy configuration mode. To disable automatic synchronization, use the no form of this command. For the Performance Routing Engines (PREs) on the Cisco uBR10012 universal broadband router, the system defaults to synchronizing all system files on the (auto-sync standard ). For the Supervisor Engines on the Cisco 7600 series routers, the system defaults to synchronizing the running configuration. (running-config ). At the Cisco RF Gateway 10 chassis level, all the system files are synchronized by default. Redundancy configuration (config-r) Main CPU redundancy configuration (config-r-mc) Cisco 7600 Series Routers If you enter the no auto-sync standard command, no automatic synchronizations occur. If you want to enable any of the keywords, you have to enter the appropriate command for each keyword. The auto-sync command is not supported in RPR+ mode. Cisco uBR10012 Universal Broadband Router By default, the system synchronizes all system files, which is the typical setting for most applications. However, you might want exclude certain files from synchronization for specialized applications. For example, if you have configured the active and standby PRE1 (or PRE2) modules to run different versions of Cisco IOS software, you might want to use different configuration files as well. In this case, you would not synchronize the startup configuration file. Cisco RF Gateway 10 We recommend that you use the auto-sync standard command to ensure that all system files are synchronized between the two Supervisor modules. The no auto-sync command is not used in production plants.", "auto-sync {startup-config | config-register | bootvar | running-config | standard} no auto-sync {startup-config | config-register | bootvar | standard}")
	k["autoupgrade disk-cleanup"] = NewKeyword("autoupgrade disk-cleanup", "To configure the Cisco IOS Auto-Upgrade Manager disk cleanup utility, use the autoupgrade disk-cleanup command in global configuration mode. To disable this configuration, use the no form of this command. By default, the crashinfo files, the core files, and the Cisco software images are deleted by the Cisco IOS Auto-Upgrade Manager disk cleanup utility, and the filesystems that support the undelete operation are not cleaned up. Global configuration (config)", "autoupgrade disk-cleanup [crashinfo | core | image | irrecoverable] no autoupgrade disk-cleanup [crashinfo | core | image | irrecoverable]")
	k["autoupgrade ida url"] = NewKeyword("autoupgrade ida url", "To configure the URL of the Intelligent Download Application (IDA) running on www.cisco.com, use the autoupgrade ida url command in global configuration mode. To disable this URL, use the no form of this command. Default URL: https://www.cisco.com/cgi-bin/ida/locator/locator.pl Global configuration (config) Use the autoupgrade ida url command to configure a new URL for the IDA server, if it is not present in the default location. The device sends the image download requests to the configured URL.", "autoupgrade ida url url no autoupgrade ida url url")
	k["autoupgrade status email"] = NewKeyword("autoupgrade status email", "To configure the address to which status email is to be sent and the outgoing email server, use the autoupgrade status email command in global configuration mode. To disable status email, use the no form of this command. Status email is not sent unless the address is configured. The recipient email address and SMTP server have to be configured in order to receive AUM status email. Global configuration (config) Use this command to configure the email-address where AUM status email can be sent.", "autoupgrade status email [recipient [email-address] ] [smtp-server [smtp-server] ] no autoupgrade status email [recipient [email-address] ] [smtp-server [smtp-server] ]")
	k["banner exec"] = NewKeyword("banner exec", "To specify and enable a message to be displayed when an EXEC process is created (an EXEC banner), use the banner exec command in global configuration mode. To delete the existing EXEC banner, use the no form of this command. Disabled (no EXEC banner is displayed). Global configuration This command specifies a message to be displayed when an EXEC process is created (a line is activated, or an incoming connection is made to a vty). Follow this command with one or more blank spaces and a delimiting character of your choice. Then enter one or more lines of text, terminating the message with the second occurrence of the delimiting character. When a user connects to a router, the message-of-the-day (MOTD) banner appears first, followed by the login banner and prompts. After the user logs in to the router, the EXEC banner or incoming banner will be displayed, depending on the type of connection. For a reverse Telnet login, the incoming banner will be displayed. For all other connections, the router will display the EXEC banner. To disable the EXEC banner on a particular line or lines, use the no exec-banner line configuration command. To customize the banner, use tokens in the form $(token ) in the message text. Tokens will display current Cisco IOS configuration variables, such as the router’s host name and IP address. The tokens are described in the table below.", "banner exec d message d no banner exec")
	k["banner incoming"] = NewKeyword("banner incoming", "To define and enable a banner to be displayed when there is an incoming connection to a terminal line from a host on the network, use the banner incoming command in global configuration mode. To delete the incoming connection banner, use the no form of this command. Disabled (no incoming banner is displayed). Global configuration Follow the banner incoming command with one or more blank spaces and a delimiting character of your choice. Then enter one or more lines of text, terminating the message with the second occurrence of the delimiting character. An incoming connection is one initiated from the network side of the router. Incoming connections are also called reverse Telnet sessions. These sessions can display MOTD banners and incoming banners, but they do not display EXEC banners. Use the no motd-banner line configuration command to disable the MOTD banner for reverse Telnet sessions on asynchronous lines. When a user connects to the router, the message-of-the-day (MOTD) banner (if configured) appears first, before the login prompt. After the user successfully logs in to the router, the EXEC banner or incoming banner will be displayed, depending on the type of connection. For a reverse Telnet login, the incoming banner will be displayed. For all other connections, the router will display the EXEC banner. Incoming banners cannot be suppressed. If you do not want the incoming banner to appear, you must delete it with the no banner incoming command. To customize the banner, use tokens in the form $(token ) in the message text. Tokens will display current Cisco IOS configuration variables, such as the router’s host name and IP address. The tokens are described in the table below.", "banner incoming d message d no banner incoming")
	k["banner login"] = NewKeyword("banner login", "To define and enable a customized banner to be displayed before the username and password login prompts, use the banner login command in global configuration mode. To disable the login banner, use no form of this command. Disabled (no login banner is displayed). Global configuration Follow the banner login command with one or more blank spaces and a delimiting character of your choice. Then enter one or more lines of text, terminating the message with the second occurrence of the delimiting character. When a user connects to the router, the message-of-the-day (MOTD) banner (if configured) appears first, followed by the login banner and prompts. After the user successfully logs in to the router, the EXEC banner or incoming banner will be displayed, depending on the type of connection. For a reverse Telnet login, the incoming banner will be displayed. For all other connections, the router will display the EXEC banner. To customize the banner, use tokens in the form $(token ) in the message text. Tokens will display current Cisco IOS configuration variables, such as the router’s host name and IP address. The tokens are described in the table below.", "banner login d message d no banner login")
	k["banner motd"] = NewKeyword("banner motd", "To define and enable a message-of-the-day (MOTD) banner, use the banner motd command in global configuration mode. To delete the MOTD banner, use the no form of this command. Disabled (no MOTD banner is displayed). Global configuration Follow this command with one or more blank spaces and a delimiting character of your choice. Then enter one or more lines of text, terminating the message with the second occurrence of the delimiting character. This MOTD banner is displayed to all terminals connected and is useful for sending messages that affect all users (such as impending system shutdowns). Use the no exec-banner or no motd-banner command to disable the MOTD banner on a line. The no exec-banner command also disables the EXEC banner on the line. When a user connects to the router, the MOTD banner appears before the login prompt. After the user logs in to the router, the EXEC banner or incoming banner will be displayed, depending on the type of connection. For a reverse Telnet login, the incoming banner will be displayed. For all other connections, the router will display the EXEC banner. To customize the banner, use tokens in the form $(token ) in the message text. Tokens will display current Cisco IOS configuration variables, such as the router’s host name and IP address. The tokens are described in the table below.", "banner motd d message d no banner motd")
	k["banner slip-ppp"] = NewKeyword("banner slip-ppp", "To customize the banner that is displayed when a Serial Line Internet Protocol (SLIP) or PPP connection is made, use the banner slip-ppp command in global configuration mode. To restore the default SLIP or PPP banner, use the no form of this command. The default SLIP or PPP banner message is: The banner message when using the service old-slip-prompt command is: where encapsulation is SLIP or PPP. Global configuration Follow this command with one or more blank spaces and a delimiting character of your choice. Then enter one or more lines of text, terminating the message with the second occurrence of the delimiting character. Use this command to define a custom SLIP or PPP connection message. This is useful when legacy client applications require a specialized connection string. To customize the banner, use tokens in the form $(token ) in the message text. Tokens will display current Cisco IOS configuration variables, such as the routers host name, IP address, encapsulation type, and Maximum Transfer Unit (MTU) size. The banner tokens are described in the table below.", "banner slip-ppp d message d no banner slip-ppp")
	k["boot bootldr"] = NewKeyword("boot bootldr", "To specify the location of the boot image that ROM uses for booting, use the boot bootldr command in global configuration mode. To remove this boot image specification, use the no form of this command. Refer to your platform documentation for the location of the default boot image. Global configuration (config) The boot bootldr command sets the BOOTLDR variable in the current running configuration. You must specify both the Flash file system and the filename. The no form of the command sets the BOOTLDR variable to a null string. On the Cisco 7000 family routers , a null string causes the first image file in boot Flash memory to be used as the boot image that ROM uses for booting. Use the show boot command to display the current value for the BOOTLDR variable.", "boot bootldr file-url boot bootldr command no boot bootldr")
	k["boot bootstrap"] = NewKeyword("boot bootstrap", "To configure the filename that is used to boot a secondary bootstrap image, use the boot bootstrap command in global configuration mode. To disable booting from a secondary bootstrap image, use the no form of this command. No secondary bootstrap is configured. Global configuration (config) The boot bootstrap command causes the router to load a secondary bootstrap image from the specied URL, such as from a remote server. After the bootstrap image is loaded, the bootstrap image loads the specified system image file. See the appropriate hardware installation guide for details on setting the configuration register and secondary bootstrap filename. Use this command when you have attempted to load a system image but have run out of memory even after compressing the system image. Secondary bootstrap images allows you to load a larger system image through a smaller secondary image.", "boot bootstrap file-url no boot bootstrap file-url boot bootstrap flash [filename] no boot bootstrap flash [filename] boot bootstrap [tftp] filename [ip-address] no boot bootstrap [tftp] filename [ip-address] boot bootstrap mop filename [interface-type interface-number] no boot bootstrap mop filename [interface-type interface-number]")
	k["boot config"] = NewKeyword("boot config", "To s pecify the device and filename of the configuration file from which the system configures itself during initialization (startup), use the boot config command in global configuration mode. To return to the default location for the configuration file, use the no form of this command. The default location for the configuration file is NVRAM (nvram: ). Global configuration (config) This command is available only on Class A and Class B file system platforms. You set the CONFIG_FILE environment variable in the current running memory when you use the boot config command. This variable specifies the configuration file used for initialization (startup). The configuration file must be an ASCII file located in either NVRAM or flash memory. The valid values for the device : argument and colon are as follows: The configuration file must be an ASCII file that is located in the specified file system. The disk0: and disk1: keywords are for Class C file systems. The bootflash: , slot0: , and sup-bootflash: keywords are for Class A file systems. For Class A flash file systems, the CONFIG_FILE environment variable specifies the file system and filename of the configuration file to use for initialization (startup). You set the CONFIG_FILE environment variable in the current running memory when you use the boot config command. This variable specifies the configuration file used for initialization (startup). When you use the boot config command, you affect only the running configuration. You must save the environment variable setting to your startup configuration to place the information under ROM monitor control and to have the environment variable function as expected. Use the copy system:running-config nvram:startup-config command to save the environment variable from your running configuration to your startup configuration. The software displays an error message and does not update the CONFIG_FILE environment variable in the following situations: The router uses the NVRAM configuration during initialization when the CONFIG_FILE environment variable does not exist or when it is null (such as at first-time startup). If the software detects a problem with NVRAM or the configuration it contains, the device enters setup mode. When you use the no form of this command, the router returns to using the default NVRAM configuration file as the startup configuration. You can display the contents of the BOOT, BOOTLDR, and the CONFIG_FILE environment variables using the show bootvar command. This command displays the settings for these variables as they exist in the startup configuration and in the running configuration if a running configuration setting differs from a startup configuration setting. When the boot config command is used, the distilled configuration is written into NVRAM and the system configuration is written into the file specified by the boot config command. If the distilled configuration exceeds the size of NVRAM, the system configuration gets truncated. Use the nvbypass keyword to prevent the system configuration from being truncated when the distilled configuration is larger than the size of NVRAM.", "Platforms Other than Cisco 7600 Series Router boot config file-system-prefix: [directory/] filename [nvbypass] no boot config Cisco 7600 Series Router boot config device:filename [nvbypass] no boot config")
	k["boot host"] = NewKeyword("boot host", "To specify the host-specific configuration file to be used at the next system startup, use the boot host command in global configuration mode. To restore the host configuration filename to the default, use the no form of this command. If you do not specify a filename using this command, the router uses its configured host name to request a configuration file from a remote server. To form the configuration filename, the router converts its name to all lowercase letters, removes all domain information, and appends -confg or -config. Global configuration This command instructs the system to “Boot using host-specific configuration file x ,” where x is the filename specified in the remote-url argument. In other words, this command specifies the remote location and filename of the host-specific configuration file to be used at the next system startup, as well as the protocol to be used to obtain the file. Before using the boot host command, use the service config global configuration command to enable the loading of the specified configuration file at reboot time. Without this command, the router ignores the boot host command and uses the configuration information in NVRAM. If the configuration information in NVRAM is invalid or missing, the service config command is enabled automatically. The network server will attempt to load two configuration files from remote hosts. The first is the network configuration file containing commands that apply to all network servers on a network. Use the boot network command to identify the network configuration file. The second is the host configuration file containing commands that apply to one network server in particular. Use the boot host command to identify the host configuration file. Loading a Configuration File Using rcp The rcp software requires that a client send the remote username on each rcp request to the network server. If the server has a directory structure (such as UNIX systems), the rcp implementation searches for the configuration files starting in the directory associated with the remote username. When you load a configuration file from a server using rcp, the Cisco IOS software sends the first valid username in the following list: Loading a Configuration File Using FTP The FTP protocol requires a client to send a remote username and password on each FTP request to a server. The username and password must be associated with an account on the FTP server. If the server has a directory structure, the configuration file or image copied from the directory is associated with the username on the server. Refer to the documentation for your FTP server for more details. When you load a configuration file from a server using FTP, the Cisco IOS software sends the first valid username in the following list: The router sends the first valid password in the following list:", "boot host commandboot host remote-url no boot host remote-url")
	k["boot network"] = NewKeyword("boot network", "To change the default name of the network configuration file from which to load configuration commands, use the boot network command in global configuration mode. To restore the network configuration filename to the default, use the no form of this command. The default filename is network-config. Global configuration This command instructs the system to “Boot using network configuration file x ,” where x is the filename specified in the remote-url argument. This command specifies the remote location and filename of the network configuration file to be used at the next system startup, as well as the protocol to be used to obtain the file. When booting from a network server, routers ignore routing information, static IP routes, and bridging information. As a result, intermediate routers are responsible for handling FTP, rcp, or TFTP requests. Before booting from a network server, verify that a server is available by using the ping command. Use the service config command to enable the loading of the specified configuration file at reboot time. Without this command, the router ignores the boot network command and uses the configuration information in NVRAM. If the configuration information in NVRAM is invalid or missing, the service config command is enabled automatically. The network server will attempt to load two configuration files from remote hosts. The first is the network configuration file containing commands that apply to all network servers on a network. Use the boot network command to identify the network configuration file. The second is the host configuration file containing commands that apply to one network server in particular. Use the boot host command to identify the host configuration file. Loading a Configuration File Using rcp The rcp software requires that a client send the remote username on each rcp request to the network server. If the server has a directory structure (such as UNIX systems), the rcp implementation searches for the configuration files starting in the directory associated with the remote username. When you load a configuration file from a server using rcp, the Cisco IOS software sends the first valid username in the following list: Loading a Configuration File Using FTP The FTP protocol requires a client to send a remote username and password on each FTP request to a server. The username and password must be associated with an account on the FTP server. If the server has a directory structure, the configuration file or image copied from the directory associated with the username on the server. Refer to the documentation for your FTP server for more details. When you load a configuration file from a server using FTP, the Cisco IOS software sends the first valid username in the following list: The router sends the first valid password in the following list:", "boot network remote-url no boot network remote-url")
	k["boot system"] = NewKeyword("boot system", "To specify the system image that the router loads at startup, use one of the following boot system command in global configuration mode. To remove the startup system image specification, use the no form of this command. If you configure the router to boot from a network server but do not specify a system image file with the boot system command, the router uses the configuration register settings to determine the default system image filename. The router forms the default boot filename by starting with the word cisco and then appending the octal equivalent of the boot field number in the configuration register, followed by a hyphen (-) and the processor type name (cisconn-cpu). Refer to the appropriate hardware installation guide for details on the configuration register and default filename. See also the config-register or confreg command. Global configuration For this command to work, the config-register command must be set properly. Create a comma-delimited list of several boot system commands to provide a fail-safe method for booting your router. The router stores and executes the boot system commands in the order in which you enter them in the configuration file. If you enter multiple boot commands of the same type--for example, if you enter two commands that instruct the router to boot from different network servers--the router tries them in the order in which they appear in the configuration file. If a boot system command entry in the list specifies an invalid device, the router omits that entry. Use the boot system rom command to specify use of the ROM system image as a backup to other boot system commands in the configuration. For some platforms, the boot image must be loaded before the system image is loaded. However, on many platforms, the boot image is loaded only if the router is booting from a network server or if the flash file system is not specified. If the file system is specified, the router will boot faster because it need not load the boot image first. This section contains the following topics: Changing the List of Boot System Commands To remove a single entry from the bootable image list, use the no form of the command with an argument. For example, to remove the entry that specifies a bootable image on a flash memory card inserted in the second slot, use the no boot system flash slot1: filename ] command. All other entries in the list remain. To eliminate all entries in the bootable image list, use the no boot system command. At this point, you can redefine the list of bootable images using the previous boot system commands. Remember to save your changes to your startup configuration by issuing the copy system:running-config nvram:startup-config command. Each time you write a new software image to flash memory, you must delete the existing filename in the configuration file with the no boot system flash filename command. Then add a new line in the configuration file with the boot system flash filename command. Booting Compressed Images You can boot the router from a compressed image on a network server. When a network server boots software, both the image being booted and the running image must be able to fit into memory. Use compressed images to ensure that enough memory is available to boot the router. You can compress a software image on any UNIX platform using the compress command. Refer to your UNIX platform’s documentation for the exact usage of the compress command. (You can also uncompress data with the UNIX uncompress command.) Understanding rcp The rcp requires that a client send the remote username in an rcp request to a server. When the router executes the boot system rcp command, the Cisco IOS software sends the hostname as both the remote and local usernames by default. Before the rcp can execute properly, an account must be defined on the network server for the remote username configured on the router. If the server has a directory structure, the rcp software searches for the system image to boot from the remote server relative to the directory of the remote username. By default, the router software sends the hostname as the remote username. You can override the default remote username by using the ip rcmd remote-username command. For example, if the system image resides in the home directory of a user on the server, you can specify that user’s name as the remote username. Understanding TFTP You need a TFTP server running to retrieve the router image from the host. Understanding FTP You need an FTP server running to retrieve the router image from the host. You also need an account on the server or anonymous file access to the server. Stopping Booting and Entering ROM Monitor Mode During the first 60 seconds of startup, you can force the router to stop booting by pressing the Break key. The router will enter ROM monitor mode, where you can change the configuration register value or boot the router manually. Cisco 1600 Series, Cisco 3600 Series, Cisco 7000 Family, and Cisco 7600 Series Router Notes For the Cisco 3600 series and Cisco 7000 family, the boot system command modifies the BOOT variable in the running configuration. The BOOT variable specifies a list of bootable images on various devices. To display the contents of the BOOT variable, use the show bootvar EXEC command.", "Loading System Image from a URL or a TFTP File boot system {file-url | filename} no boot system {file-url | filename} Booting from a System Image in Internal Flash boot system flash [flash-fs:] [partition-number:] [filename] no boot system flash [flash-fs:] [partition-number:] [filename] Booting from a MOP Server boot system mop filename [mac-address] [interface] no boot system mop filename [mac-address] [interface] Booting from ROM boot system rom no boot system rom Booting a System Image from a Network, TFTP, or FTP Server boot system {rcp | tftp | ftp} filename [ip-address] no boot system {rcp | tftp | ftp} filename [ip-address]")
	k["clock"] = NewKeyword("clock", "To configure the port clocking mode for the 1000BASE-T transceivers, use the clock command in interface configuration mode. To return to the default settings,use the no form of this command. auto Interface configuration This command is supported on the 1000BASE-T transceivers only. If the clock mode of the near end of a link does not match the clock mode of the far end, the line protocol does not come up. The active and passive clock status is determined during the auto negotiation process before the transmission link is established. The clock command supports the following configurations: Enter the show running-config interface command to display the current clock mode. Enter the show interfaces command to display the clock mode that is negotiated by the firmware.", "clock {auto | active [prefer] | passive [prefer]} no clock")
	k["clock initialize nvram"] = NewKeyword("clock initialize nvram", "To restart the system clock from the last known system clock value, use the clock initialize nvram command in global configuration mode. To disable the restart of the system clock from the last known system clock value, use the no form of this command. This command has no arguments or keywords. By default, the system clock is set to restart from the last known system clock value for platforms that have no hardware calendar. Global configuration (config) For platforms that have hardware calendars, the clock initialize nvram command is not available. When the no form of the command is configured, the system clock gets initialized to default standard values. The default values can be either 1MAR1993 or 1MAR2002.", "clock initialize nvram no clock initialize nvram")
	k["config-register"] = NewKeyword("config-register", "To change the configuration register settings, use the config-register command in global configuration mode. Refer to the documentation for your platform for the default configuration register value. For many newer platforms, the default is 0x2102, which causes the router to boot from Flash memory and the Break key to be ignored. Global configuration This command applies only to platforms that use a software configuration register. The lowest four bits of the configuration register (bits 3, 2, 1, and 0) form the boot field. The boot field determines if the router boots manually, from ROM, or from Flash or the network. To change the boot field value and leave all other bits set to their default values, follow these guidelines: For more information about the configuration register bit settings and default filenames, refer to the appropriate router hardware installation guide.", "config-register value")
	k["configuration mode exclusive"] = NewKeyword("configuration mode exclusive", "To enable single-user (exclusive) access functionality for the Cisco CLI, use the configuration mode exclusive command in global configuration mode. To disable the single-user access (configuration locking) feature, use the no form of this command. Single-user mode is disabled. Global configuration (config) The configuration mode exclusive command enables the exclusive configuration lock feature. The exclusive configuration lock allows single-user access to configuration modes using single-user configuration mode. While the device configuration is locked, no other users can enter configuration commands. Users accessing the device using the state-full, session-based transports (telnet, Secure Shell (SSH) are able to enter single-user configuration mode. The user enters single-user configuration mode by acquiring the exclusive configuration lock using the configure terminal lock privileged EXEC mode command. The configuration lock is released when the user exits configuration mode by using the end or exit command, or by pressing Ctrl-Z. While a user is in single-user configuration mode, no other users can configure the device. Users accessing Command Line Interface (CLI) options through stateless protocols (that is, the HTTP web-based user interface) cannot access single-user configuration mode. (However, an Application Programming Interface (API) allows the stateless transports to lock the configuration mode, complete its operations, and release the lock.)", "configuration mode exclusive {auto | manual} [expire seconds] [lock-show] [interleave] [terminate] [config-wait seconds] [retry-wait seconds] no configuration mode exclusive")
	k["databits"] = NewKeyword("databits", "To set the number of data bits per character that are interpreted and generated by the router hardware, use the databits command in line configuration mode. To restore the default value, use the no form of the command. Eight data bits per character Line configuration The databits line configuration command can be used to mask the high bit on input from devices that generate 7 data bits with parity. If parity is being generated, specify 7 data bits per character. If no parity generation is in effect, specify 8 data bits per character. The other keywords are supplied for compatibility with older devices and generally are not used.", "databits {5 | 6 | 7 | 8} no databits")
	k["data-character-bits"] = NewKeyword("data-character-bits", "To set the number of data bits per character that are interpreted and generated by the Cisco IOS software, use the data-character-bits command in line configuration mode. To restore the default value, use the no form of this command. Eight data bits per character Line configuration The data-character-bits line configuration command is used primarily to strip parity from X.25 connections on routers with the protocol translation software option. The data-character-bits line configuration command does not work on hard-wired lines.", "data-character-bits {7 | 8} no data-character-bits")
	k["default-value data-character-bits"] = NewKeyword("default-value data-character-bits", "To configure the number of data bits per character that are generated and interpreted by Cisco software to either 7 bits or 8 bits, use the default-value data-character-bits command in global configuration mode. To disable the configured size, use the no form of this command. 8 data bits per character are generated. Global configuration (config)", "default-value data-character-bits {7 | 8} no default-value data-character-bits")
	k["default-value exec-character-bits"] = NewKeyword("default-value exec-character-bits", "To define the EXEC character width for either 7 bits or 8 bits, use the default-value exec-character-bits command in global configuration mode. To restore the default value, use the no form of this command. 7-bit ASCII character set Global configuration Configuring the EXEC character width to 8 bits allows you to add graphical and international characters in banners, prompts, and so on. However, setting the EXEC character width to 8 bits can also cause failures. If a user on a terminal that is sending parity enters the help command, an “unrecognized command” message appears because the system is reading all 8 bits, although the eighth bit is not needed for the help command.", "default-value exec-character-bits {7 | 8} no default-value exec-character-bits")
	k["default-value modem-interval"] = NewKeyword("default-value modem-interval", "To configure the default frequency time to scan modem signals, use the default-value modem-interval command in global configuration mode. To disable the configured frequency, use the no form of this command. The frequency time to scan modem signals is 50 ms. Global configuration (config)", "default-value modem-interval milliseconds no default-value modem-interval")
	k["default-value special-character-bits"] = NewKeyword("default-value special-character-bits", "To configure the flow control default value from a 7-bit width to an 8-bit width, use the default-value special-character-bits command in global configuration mode. To restore the default value, use the no form of this command. 7-bit character set Global configuration Configuring the special character width to 8 bits allows you to add graphical and international characters in banners, prompts, and so on.", "default-value special-character-bits commanddefault-value special-character-bits {7 | 8} no default-value special-character-bits")
	k["define interface-range"] = NewKeyword("define interface-range", "To create an interface-range macro, use the define interface-range command in global configuration mode. To remove an interface-range macro, use the no form of this command. Interface-range macro is not configured. Global configuration (config)", "define interface-range macro-name interface-range")
	k["diagnostic bootup level"] = NewKeyword("diagnostic bootup level", "To set the diagnostic bootup level, use the diagnostic bootup level command in global configuration mode. To skip all diagnostic tests, use the no form of this command. minimal Global configuration (config) Setting the diagnostic level determines the level of testing that occurs when the system or module is reset. The two levels are as follows: In certain circumstances, you might want to skip the bootup online diagnostics completely. For example, you might skip the bootup online diagnostics to verify that a port is as bad as online diagnostics reports. To skip online diagnostic testing completely, use the no diagnostic bootup level command. For information on the diagnostic test types, use the show diagnostic command. The new level takes effect at the next reload or the next time that an online insertion and removal is performed.", "diagnostic bootup level {minimal | complete} no diagnostic bootup level")
	k["diagnostic cns"] = NewKeyword("diagnostic cns", "To configure the Cisco Networking Services (CNS) diagnostics, use the diagnostic cns command in global configuration mode. To disable sending diagnostic results to the CNS event bus., use the no form of this command. The following are the default settings for diagnostic cns: diagnostic cns publish cisco.cns.device.diag_results diagnostic cns subscribe cisco.cns.device.diag_commands Global configuration The online diagnostics receive events by subscribing to an event subject name. The subject is the event that you subscribe (receive) or publish (generate) through the CNS bus. The diagnostic cns publish command sends diagnostic results to a remote network application to make decisions and take corrective actions that are based on the diagnostic results. The diagnostic cns subscribe command receives messages from remote network applications to perform diagnostic tests or retrieve diagnostic results.", "diagnostic cns {publish | subscribe} [subject] no diagnostic cns {publish | subscribe} [subject]")
	k["diagnostic event-log size"] = NewKeyword("diagnostic event-log size", "To modify the diagnostic event log size dynamically, use the diagnostic event-log size command in global configuration mode. To return to the default settings, use the no form of this command. The event log size is 500 entries. Global configuration (config) The events are dynamically allocated and stored in a circular queue. You can enter either the default diagnostic event-log size command or the no diagnostic event-log size command to return to the default settings.", "diagnostic event-log size size no diagnostic event-log size")
	k["diagnostic monitor"] = NewKeyword("diagnostic monitor", "To configure health-monitoring diagnostic testing, use the diagnostic monitor command in global configuration mode. To disable testing, use the no form of this command. The defaults are as follows: Global configuration (config) Use these guidelines when scheduling testing: Enter the [no ] diagnostic monitor test {test-id | test-id-range | all } command to enable or disable the specified health monitoring test. When entering the diagnostic monitor module number test {test-id | test-id-range | all } command, observe the following: The FIB TCAM test for central PFC3BXL or PFC3B (on the supervisor engine) takes approximately 4 hours and 30 minutes. The FIB TCAM test for the distributed PFC3BXL or PFC3B (on the DFC module) takes approximately 16 hours. You can run the FIB TCAM test on multiple DFC3BX modules simultaneously. Cisco UBR10012 Router The command syntax to refer a line card or SPAs is different on Cisco UBR10012 Router. The keyword is slot x for a full-height line card, slot x/y for a half-height card, and bay x/y for a SPA. To monitor a diagnostic test periodically, you first need to configure the hours, minutes, and seconds interval to run the diagnostic test using the diagnostic monitor interval command. An error message is displayed, if the interval is not configured before enabling the monitoring. To store log details for failed tests, execute the diagnostic monitor syslog command. A threshold value to specify the maximum count for allowed failures is configured using the diagnostic monitor threshold command. The failed test results can be viewed using the show diagnostic results command, after the number of failed test reaches the maximum number of allowed failures configured using the diagnostic monitor threshold command.", "diagnostic monitor intervalmodule number test {test-id | test-id-range | all} hh:mm:ss milliseconds days diagnostic monitor syslog diagnostic monitor module num test {test-id | test-id-range | all} no diagnostic monitor {interval | syslog} Cisco UBR10012 Router diagnostic monitor {bay slot/ bay | slot slot number | subslot slot/ subslot} test {test-id | test-id-range | all} diagnostic monitor interval {bay slot/ bay | slot slot-no | subslot slot/ subslot} test {test-id | test-id-range | all} hh:mm:ss milliseconds days diagnostic monitor syslog diagnostic monitor threshold {bay slot/ bay | slot slot-no | subslot slot/ subslot} test {test-id | test-id-range | all} failure count failures [ {runs | days | hours | minutes | seconds | milliseconds} window_size]")
	k["diagnostic schedule module"] = NewKeyword("diagnostic schedule module", "To set the scheduling of test-based diagnostic testing for a specific module or schedule a supervisor engine switchover, use the diagnostic schedule module command in global configuration mode. To remove the scheduling, use the no form of this command. Test-based diagnostic testing for a specific module is not scheduled. Global configuration (config) Use these guidelines when scheduling testing: You can use the diagnostic schedule module slot / subslot test test-id command to schedule a switchover from the active supervisor engine to the standby supervisor engine. Enter the show diagnostic content module slot / subslot command to display the test ID list and look for the test ID in the ScheduleSwitchover field. You can specify a periodic switchover (daily or weekly) or a single switchover occurrence at a specific time using these commands:", "diagnostic schedule module {module-number | slot/subslot} test {test-id | all | complete | minimal | non-disruptive | [per-port [port {interface-port-number | port-number-list | all}]]} {on month dd yyyy hh:mm | daily hh:mm | weekly day-of-week hh:mm} no diagnostic schedule module {module-number | slot/subslot} test {test-id | all | complete | minimal | non-disruptive | [per-port [port {interface-port-number | port-number-list | all}]]} {on month dd yyyy hh:mm | daily hh:mm | weekly day-of-week hh:mm}")
	k["disconnect-character"] = NewKeyword("disconnect-character", "To define a character to disconnect a session, use the disconnect-character command in line configuration mode. To remove the disconnect character, use the no form of this command. No disconnect character is defined. Line configuration See the “ASCII Character Set and Hex Values” appendix for a list of ASCII characters. The Break character is represented by zero; NULL cannot be represented. To use the session-disconnect character in normal communications, precede it with the escape character.", "disconnect-character ascii-number no disconnect-character")
	k["dispatch-character"] = NewKeyword("dispatch-character", "To define a character that causes a packet to be sent, use the dispatch-character command in line configuration mode. To remove the definition of the specified dispatch character, use the no form of this command. No dispatch character is defined. Line configuration See the “ASCII Character Set and Hex Values” appendix for a list of ASCII characters. The dispatch-character command defines one or more dispatch characters that cause a packet to be sent even if the dispatch timer has not expired. Use of a dispatch character causes the Cisco IOS software to attempt to buffer characters into larger-sized packets for transmission to the remote host. Enable the dispatch-character command from the session that initiates the connection, not from the incoming side of a streaming Telnet session. This command can take multiple arguments, so you can define any number of characters as dispatch characters.", "dispatch-character ascii-number1 [ascii-number2. . . ] no dispatch-character ascii-number1 [ascii-number2. . . ]")
	k["dispatch-machine"] = NewKeyword("dispatch-machine", "To specify an identifier for a TCP packet dispatch state machine on a particular line, use the dispatch-machine command in line configuration mode. To disable a state machine on a particular line, use the no form of this command. No dispatch state machine identifier is defined. Line configuration When the dispatch-timeout command is specified, a packet being built will be sent when the timer expires, and the state will be reset to zero. Any dispatch characters specified using the dispatch-character command are ignored when a state machine is also specified. If a packet becomes full, it will be sent regardless of the current state, but the state will not be reset. The packet size depends on the traffic level on the asynchronous line and the dispatch-timeout value. There is always room for 60 data bytes. If the dispatch-timeout value is greater than or equal to 100 milliseconds, a packet size of 536 (data bytes) is allocated.", "dispatch-machine name no dispatch-machine")
	k["dispatch-timeout"] = NewKeyword("dispatch-timeout", "To set the character dispatch timer, use the dispatch-timeout command in line configuration mode. To remove the timeout definition, use the no form of this command. No dispatch timeout is defined. Line configuration Use this command to increase the processing efficiency for the remote host. The dispatch-timeout line configuration command causes the software to buffer characters into packets for transmission to the remote host. The Cisco IOS software sends a packet a specified amount of time after the first character is put into the buffer. You can use the dispatch-timeout and dispatch-character line configuration commands together. In this case, the software dispatches a packet each time the dispatch character is entered, or after the specified dispatch timeout interval, depending on which condition is met first.", "dispatch-timeout milliseconds no dispatch-timeout")
	k["do"] = NewKeyword("do", "To execute user EXEC or privileged EXEC commands from global configuration mode or other configuration modes or submodes, use the do command in any configuration mode. A user EXEC or privileged EXEC command is not executed from a configuration mode. All configuration modes Use this command to execute user EXEC or privileged EXEC commands (such as show , clear , and debug commands) while configuring your routing device. After the EXEC command is executed, the system will return to the configuration mode you were using. You cannot use the do command to execute the configure terminal c ommand because entering the configure terminal command changes the user EXEC mode or privileged EXEC mode to the global configuration mode. You cannot use the do command to execute copy or write c ommands in the global configuration or any other configuration mode or submode.", "do command")
	k["downward-compatible-config"] = NewKeyword("downward-compatible-config", "To generate a configuration that is compatible with an earlier Cisco IOS release, use the downward-compatible-config command in global configuration mode. To disable this function, use the no form of this command. The configuration is not compatible with earlier Cisco IOS releases. Global configuration (config) In Cisco IOS Release 10.3, IP access lists changed format. Use the downward-compatible-config command to regenerate a configuration in a format prior to Release 10.3 if you will downgrade from your software version to version 10.2 or 10.3. The earliest version value this command accepts is 10.2. When this command is configured, the router attempts to generate a configuration that is compatible with the specified version. Note that this command affects only IP access lists. Under some circumstances, the software might not be able to generate a fully backward-compatible configuration. In such a case, the software issues a warning message.", "downward-compatible-config version no downward-compatible-config")
	k["editing"] = NewKeyword("editing", "To reen able Cisco IOS enhanced editing features for a particular line after they have been disabled, use the editing command in line configuration mode. To disable these features, use the no form of this command. This command has no arguments or keywords. Enabled Line configuration Enhanced editing features are enabled by default. However, there may be situations in which you need to disable these features. The no form of this command disables these enhanced editing features, and the plain form of the command can be used to reenable these features. The table below provides a description of the keys used to enter and edit commands when the editing features are enabled. Ctrl indicates the Control key, which must be pressed simultaneously with its associated letter key. Esc indicates the Escape key, which must be pressed first, followed by its associated letter key. A comma is used in the following table to indicate a key sequence (the comma key should not be pressed). Keys are not case sensitive. Many letters used for CLI navigation and editing were chosen to provide an easy way of remembering their functions. In the following table, characters are bolded in the “Function Summary” column to indicate the relation between the letter used and the function.", "editing no editing")
	k["enable last-resort"] = NewKeyword("enable last-resort", "To enable password parameters as the last resort without specifying the local enable password if no TACACS servers respond, use the enable last-resort command in global configuration mode. To disable the password parameters, use the no form of this command. The password parameters for the router are not enabled. Global configuration (config)", "no enable last-resort {password | succeed} no enable last-resort")
	k["end"] = NewKeyword("end", "To en d the current configuration session and return to privileged EXEC mode, use the end command in global configuration mode. This command has no arguments or keywords. No default behavior or values. Global configuration This command will bring you back to privileged EXEC mode regardless of what configuration mode or configuration submode you are in. Use this command when you are done configuring the system and you want to return to EXEC mode to perform verification steps.", "end")
	k["environment-monitor shutdown temperature"] = NewKeyword("environment-monitor shutdown temperature", "To enable monitoring of the environment sensors, use the environment-monitor shutdown temperature command in global configuration mode. To disable monitoring of the environment sensors, use the no form of this command. By default, rommon is enabled. Global configuration", "environment-monitor shutdown temperature [rommon | powerdown] no environment-monitor shutdown temperature [rommon | powerdown]")
	k["environment temperature-controlled"] = NewKeyword("environment temperature-controlled", "To enable the ambient temperature control, use the environment temperature-controlled command in global configuration mode. To disable the ambient temperature control, use the no form of this command. This command has no arguments or keywords. This command is disabled by default. Global configuration This command does not affect temperature monitoring and alarm thresholds; it only affects whether a module may be powered on. The software does not validate the inlet temperature. If you enter the no form of this command and the cooling capacity is reduced below the module cooling requirement, a syslog warning (and SNMP alarm) is generated. This module status does not change, and an environmental alarm is not raised when you enter the no form of this command.", "environment temperature-controlled no environment temperature-controlled")
	k["errdisable detect cause"] = NewKeyword("errdisable detect cause", "To enable error-disable detection, use the errdisable detect cause command in global configuration mode. To disable error-disable detection, use the no form of this command. Error-disable detection is enabled for all causes. Global configuration (config) A cause (bpduguard, dtp-flap, link-flap, pagp-flap, root-guard, udld) is defined as the reason why the error-disable state occurred. When a cause is detected on an interface, the interface is placed in an error-disable state (an operational state that is similiar to the link-down state). You must enter the shutdown and then the no shutdown commands to recover an interface manually from the error-disable state.", "errdisable detect cause {all | bpduguard | dtp-flap | l2ptguard | link-flap | packet-buffer-error | pagp-flap | rootguard | udld} no errdisable detect cause {all | bpduguard | dtp-flap | l2ptguard | link-flap | pagp-flap | rootguard | udld}")
	k["errdisable recovery"] = NewKeyword("errdisable recovery", "To configure recovery mechanism variables, use the errdisable recovery command in global configuration mode. To return to the default state, use the no form of this command. The recovery mechanisms are disabled. Global configuration (config) A cause (bpduguard, channel-misconfig, dhcp-rate-limit, dtp-flap, l2ptguard, link-flap, pagp-flap, psecure-violation, security-violation, rootguard, udld, or unicast-flood) is defined as the reason why the error-disable state occurred. When a cause is detected on an interface, the interface is placed in an error-disable state (an operational state that is similar to the link-down state). If you do not enable error-disable recovery for the cause, the interface stays in the error-disable state until a shutdown and no shutdown occur. If you enable recovery for a cause, the interface is brought out of the error-disable state and allowed to retry operation once all the causes have timed out. You must enter the shutdown command and then the no shutdown command to manually recover an interface from the error-disable state.", "errdisable recovery {cause {all | arp-inspection | bpduguard | channel-misconfig | dhcp-rate-limit | dtp-flap | gbic-invalid | l2ptguard | link-flap | pagp-flap | psecure-violation | security-violation | rootguard | udld | unicast-flood} | interval seconds} no errdisable recovery {cause {all | arp-inspection | bpduguard | channel-misconfig | dhcp-rate-limit | dtp-flap | gbic-invalid | l2ptguard | link-flap | pagp-flap | psecure-violation | security-violation | rootguard | udld | unicast-flood} | interval seconds}")
	k["escape-character"] = NewKeyword("escape-character", "To define a system escape character, use the escape-character command in line configuration mode. To set the escape character to Break, use the no or default form of this command. The default escape key sequence is Ctrl-Shift-6 (Ctrl-^) or Ctrl-Shift-6, X (^^X). The X is generally only required for modem connections. The default escape-character command sets the escape character to Break (the default setting for Break is Ctrl-C). Line configuration See the \"ASCII Character Set and Hexidecimal Values\" appendix for a list of ASCII characters. The escape character (or key sequence) suspends any actively running processes and returns you to privileged EXEC mode or, if a menu is being used, to the system menu interface. The escape character is used for interrupting or terminating a process started by previously executed command. Examples of processes from which you can escape include Domain-Name lookup, ping , trace , and Telnet sessions initiated from the device to which you are connected. To view the current setting of the escape sequence for a line, use the show line command followed by the specific line identifier (for example, show line 0 , or show line console ). The default escape sequence for a line is often displayed as ^^X . The first caret symbol represents the Control (Ctrl) key, the second caret symbol is literal (Shift-6), and the X is literal (for most systems, the X is not required). To set the escape key for the active terminal line session, use the terminal escape-character command. The Break key cannot be used as an escape character on a console terminal because the Cisco IOS software interprets Break as an instruction to halt the system. Depending upon the configuration register setting, break commands issued from the console line either will be ignored or cause the server to shut down. To send an escape sequence over a Telnet connection, press Ctrl-Shift-6 twice. The escape-character soft form of this command defines a character or character sequence that will cause the system to wait until pending input is processed before suspending the current session. This option allows you to program a key sequence to perform multiple actions, such as using the F1 key to execute a command, then execute the escape function after the first command is executed. The following restrictions apply when using the soft keyword:", "escape-character {break | char | default | none | soft} no escape-character [soft] default escape-character [soft]")
	k["exec"] = NewKeyword("exec", "To allow an EXEC process on a line, use the exec command in line configuration mode. To turn off the EXEC process for the specified line, use the no form of this command. This command has no arguments or keywords. The EXEC processes is enabled on all lines. Line configuration When you want to allow only an outgoing connection on a line, use the no exec command. The no exec command allows you to disable the EXEC process for connections which may attempt to send unsolicited data to the router. (For example, the control port of a rack of modems attached to an auxiliary port of router.) When certain types of data are sent to a line connection, an EXEC process can start, which makes the line unavailable. When a user tries to Telnet to a line with the EXEC process disabled, the user will get no response when attempting to log on.", "exec no exec")
	k["exec-banner"] = NewKeyword("exec-banner", "To reenable the display of EXEC and message-of-the-day (MOTD) banners on the specified line or lines, use the exec-banner command in line configuration mode. To suppress the banners on the specified line or lines, use the no form of this command. This command has no arguments or keywords. Enabled on all lines Line configuration This command determines whether the router will display the EXEC banner and the message-of-the-day (MOTD) banner when an EXEC session is created. These banners are defined with the banner exec and banner motd global configuration commands. By default, these banner are enabled on all lines. Disable the EXEC and MOTD banners using the no exec-banner command. This command has no effect on the incoming banner, which is controlled by the banner incoming command. The MOTD banners can also be disabled by the no motd-banner line configuration command, which disables MOTD banners on a line. If the no exec-banner command is configured on a line, the MOTD banner will be disabled regardless of whether the motd-banner command is enabled or disabled. The table below summarizes the effects of the exec-banner command and the motd-banner command. For reverse Telnet connections, the EXEC banner is never displayed. Instead, the incoming banner is displayed. The MOTD banner is displayed by default, but it is disabled if either the no exec-banner command or no motd-banner command is configured. The table below summarizes the effects of the exec-banner command and the motd-banner command for reverse Telnet connections.", "exec-banner no exec-banner")
	k["exec-character-bits"] = NewKeyword("exec-character-bits", "To configure the character widths of EXEC and configuration command characters, use the exec-character-bits command in line configuration mode. To restore the default value, use the no form of this command. 7-bit ASCII character set Line configuration Setting the EXEC character width to 8 allows you to use special graphical and international characters in banners, prompts, and so on. However, setting the EXEC character width to 8 bits can cause failures. If a user on a terminal that is sending parity enters the help command, an “ unrecognized command” message appears because the system is reading all 8 bits, and the eighth bit is not needed for the help command.", "exec-character-bits {7 | 8} no exec-character-bits")
	k["exec-timeout"] = NewKeyword("exec-timeout", "To set the interval that the EXEC command interpreter waits until user input is detected, use the exec-timeout command in line configuration mode. To remove the timeout definition, use the no form of this command. 10 minutes Line configuration If no input is detected during the interval, the EXEC facility resumes the current connection. If no connections exist, the EXEC facility returns the terminal to the idle state and disconnects the incoming session. To specify no timeout, enter the no form of this command.", "exec-timeout minutes [seconds] no exec-timeout")
	k["exit (global)"] = NewKeyword("exit (global)", "To exit any configuration mode to the next highest mode in the CLI mode hierarchy, use the exit command in any configuration mode. This command has no arguments or keywords. No default behavior or values All configuration modes The exit command is used in the Cisco IOS CLI to exit from the current command mode to the next highest command mode in the CLI mode hierarchy. For example, use the exit command in global configuration mode to return to privileged EXEC mode. Use the exit command in interface, line, or router configuration mode to return to global configuration mode. Use the exit command in subinterface configuration mode to return to interface configuration mode. At the highest level, EXEC mode, the exit command will exit the EXEC mode and disconnect from the router interface (see the description of the exit (EXEC) command for details).", "exit")
	k["file privilege"] = NewKeyword("file privilege", "By default the privilege level is set to 15. Global configuration (config#)", "file privilege level level no file privilege level level")
	k["file prompt"] = NewKeyword("file prompt", "To specify the level of prompting, use the file prompt command in global configuration mode. alert Global configuration Use this command to change the amount of confirmation needed for different file operations. This command affects only prompts for confirmation of operations. The router will always prompt for missing information.", "file prompt prompt [alert | noisy | quiet]")
	k["file verify auto"] = NewKeyword("file verify auto", "To enable automatic image verification, use the file verify auto command in global configuration mode. To disable automatic image verification, use the no form of this command. This command has no arguments or keywords. Image verification is not automatically applied to all images that are copied or reloaded onto a router. Global configuration Image verification is accomplished by verifying the compressed Cisco IOS image checksum. Image verification allows users to automatically verify the integrity of all Cisco IOS images. Thus, users can be sure that the image is protected from accidental corruption, which can occur at any time during transit, starting from the moment the files are generated by Cisco until they reach the user. The file verify auto command enables image verification globally; that is, all images that are to be copied (via the copy command) or reloaded (via the reload command) are automatically verified. Although both the copy and reload commands have a /verify keyword that enables image verification, you must issue the keyword each time you want to copy or reload an image. The file verify auto command enables image verification by default so you no longer have to specify image verification multiple times. If you have enabled image verification by default but prefer to disable verification for a specific image copy or reload, the /noverify keyword along with either the copy or the reload command will override the file verify auto command.", "file verify auto no file verify auto")
	k["full-help"] = NewKeyword("full-help", "To get help f or the full set of user-level commands, use the full-help command in line configuration mode. This command has no arguments or keywords. Disabled Line configuration The full-help command enables (or disables) an unprivileged user to see all of the help messages available. It is used with the show ? command.", "full-help")
	k["help"] = NewKeyword("help", "To display a brief description of the help system, use the help command in any command mode. This command has no arguments or keywords. No default behavior or values. User EXEC Privileged EXEC All configuration modes The help command provides a brief description of the context-sensitive help system, which functions as follows:", "help")
	k["hidekeys"] = NewKeyword("hidekeys", "To suppress the display of password information in configuration log files, use the hidekeys command in configuration change logger configuration mode. To allow the display of password information in configuration log files, use the no form of this command. This command has no arguments or keywords. Password information is displayed. Configuration change logger configuration (config-archive-log-config) Enabling the hidekeys command increases security by preventing password information from being displayed in configuration log files.", "hidekeys no hidekeys")
	k["history"] = NewKeyword("history", "To enable the command history function, use the history command in line configuration mode. To disable the command history function, use the no form of this command. This command has no arguments or keywords. Enabled with ten command lines in the buffer. Line configuration The command history function provides a record of EXEC commands that you have entered. This function is particularly useful for recalling long or complex commands or entries, including access lists. To change the number of command lines that the system will record in its history buffer, use the history size line configuration command. The history command enables the history function with the last buffer size specified or, if there was not a prior setting, with the default of ten lines. The no history command disables the history function. The show history EXEC command will list the commands you have entered, but you can also use your keyboard to display individual commands. The table below lists the keys you can use to recall commands from the command history buffer.", "history no history")
	k["history size"] = NewKeyword("history size", "To change the command history buffer size for a particular line, use the history size command in line configuration mode. To reset the command history buffer size to ten lines, use the no form of this command. 10 command lines Line configuration The history size command should be used in conjunction with the history and show history commands. The history command enables or disables the command history function. The show history command lists the commands you have entered in the current EXEC session. The number of commands that the history buffer will show is set by the history size command.", "history size number-of-lines no history size")
	k["hold-character"] = NewKeyword("hold-character", "To define the local hold character used to pause output to the terminal screen, use the hold-character command in line configuration mode. To restore the default, use the no form of this command. No hold character is defined. Line configuration The Break character is represented by zero; NULL cannot be represented. To continue the output, enter any character after the hold character. To use the hold character in normal communications, precede it with the escape character. See the “ASCII Character Set” appendix for a list of ASCII characters.", "hold-character ascii-number no hold-character")
	k["hostname"] = NewKeyword("hostname", "To specify or modify the hostname for the network server, use the hostname command in global configuration mode. The default hostname is Router. Global configuration The hostname is used in prompts and default configuration filenames. Do not expect case to be preserved. Uppercase and lowercase characters look the same to many internet software applications. It may seem appropriate to capitalize a name the same way you might do in English, but conventions dictate that computer names appear all lowercase. For more information, refer to RFC 1178, Choosing a Name for Your Computer . The name must also follow the rules for ARPANET hostnames. They must start with a letter, end with a letter or digit, and have as interior characters only letters, digits, and hyphens. Names must be 63 characters or fewer. Creating an all numeric hostname is not recommended but the name will be accepted after an error is returned. A hostname of less than 10 characters is recommended. For more information, refer to RFC 1035, Domain Names--Implementation and Specification . On most systems, a field of 30 characters is used for the hostname and the prompt in the CLI. Note that the length of your hostname may cause longer configuration mode prompts to be truncated. For example, the full prompt for service profile configuration mode is: However, if you are using the hostname of “Router,” you will only see the following prompt (on most systems): If the hostname is longer, you will see even less of the prompt: Keep this behavior in mind when assigning a name to your system (using the hostname global configuration command). If you expect that users will be relying on mode prompts as a CLI navigation aid, you should assign hostnames of no more than nine characters. The use of a special character such as \\(backslash) and a three or more digit number for the character setting like hostname , results in incorrect translation:", "hostname name")
	k["insecure"] = NewKeyword("insecure", "To configure a line as insecure, use the insecure command in line configuration mode. To disable this function, use the no form of this command. This command has no arguments or keywords. Disabled Line configuration Use this command to identify a modem line as insecure for DEC local area transport (LAT) classification.", "insecure no insecure")
	k["international"] = NewKeyword("international", "If you are using Telnet to access a Cisco IOS platform and you want to display 8-bit and multibyte international characters (for example, Kanji) and print the Escape character as a single character instead of as the caret and bracket symbols (^[), use the international command in line configuration mode. To display characters in 7-bit format, use the no form of this command. This command has no arguments or keywords. Disabled Line configuration If you are configuring a Cisco IOS platform using the Cisco web browser user interface (UI), this function is enabled automatically when you enable the Cisco web browser UI using the ip http server global configuration command.", "international no international")
	k["ip bootp server"] = NewKeyword("ip bootp server", "To enable the Bootstrap Protocol (BOOTP) service on your routing device, use the ip bootp server command in global configuration mode. To disable BOOTP services, use the no form of the command. This command has no arguments or keywords. Enabled Global configuration By default, the BOOTP service is enabled. When disabled, the no ip bootp server command will appear in the configuration file. The integrated Dynamic Host Configuration Protocol (DHCP) server was introduced in Cisco IOS Release 12.0(1)T. Because DHCP is based on BOOTP, both of these services share the “well-known” UDP server port of 67 (per RFC 951, RFC 1534, and RFC 2131; the client port is 68). To disable DHCP services (DHCP relay and DHCP server), use the no service dhcp command. To disable BOOTP services (in releases 12.2(8)T and later), but leave DHCP services enabled, use the ip dhcp bootp ignore command. If both the BOOTP server and DHCP server are disabled, “ICMP port unreachable” messages will be sent in response to incoming requests on port 67, and the original incoming packet will be discarded. If DHCP is enabled, using the no ip bootp server command by itself will not stop the router from listening on UDP port 67.", "ip bootp server no ip bootp server")
	k["ip finger"] = NewKeyword("ip finger", "To configure a system to accept Finger protocol requests (defined in RFC 742), use the ip finger command in global configuration mode. To disable this service, use the no form of this command. Disabled Global configuration The Finger service allows remote users to view the output equivalent to the show users [wide ] command. When ip finger is configured, the router will respond to a telnet a.b.c.d finger command from a remote host by immediately displaying the output of the show users command and then closing the connection. When the ip finger rfc-compliant command is configured, the router will wait for input before displaying anything (as required by RFC 1288). The remote user can then enter the Return key to display the output of the show users EXEC command, or enter /W to display the output of the show users wide EXEC command. After this information is displayed, the connection is closed. Because of the potential for hung lines, the rfc-compliant form of this command should not be configured for devices with more than 20 simultaneous users.", "ip finger [rfc-compliant] no ip finger")
	k["ip ftp passive"] = NewKeyword("ip ftp passive", "To configure the router to use only passive FTP connections, use the ip ftp passive command in global configuration mode . To allow all types of FTP connections, use the no form of this command. This command has no arguments or keywords. All types of FTP connections are allowed. Global configuration", "ip ftp passive no ip ftp passive")
	k["ip ftp password"] = NewKeyword("ip ftp password", "To specify the password to be used for File Transfer Protocol (FTP) connections, use the ip ftp password command in global configuration mode. To return the password to its default, use the no form of this command. The router forms a password username @routername .domain . The variable username is the username associated with the current session, routername is the configured host name, and domain is the domain of the router. Global configuration", "ip ftp password [type] password no ip ftp password")
	k["ip ftp source-interface"] = NewKeyword("ip ftp source-interface", "To specify the source IP address for File Transfer Protocol (FTP) connections, use the ip ftp source-interface command in global configuration mode. To use the address of the interface where the connection is made, use the no form of this command. The FTP source address is the IP address of the interface that the FTP packets use to leave the router. Global configuration (config) Use this command to set the same source address for all FTP connections. In Cisco IOS 12.3(6) and later releases, FTP is VRF-aware, which means that FTP transfer is supported across an interface within a VRF instance. To specify a VRF as a source for FTP connections, the VRF must be associated with the same interface that you configure with the ip ftp source-interface command. In this configuration, FTP looks for the destination IP address for file transfer in the specified VRF table. If the specified source interface is not up, Cisco IOS software selects the address of the interface closest to the destination as the source address.", "ip ftp source-interface interface-type interface-number no ip ftp source-interface")
	k["ip ftp username"] = NewKeyword("ip ftp username", "To configure the username for File Transfer Protocol (FTP) connections, use the ip ftp username command in global configuration mode . To configure the router to attempt anonymous FTP, use the no form of this command. The Cisco IOS software attempts an anonymous FTP. Global configuration The remote username must be associated with an account on the destination server.", "ip ftp username username no ip ftp username")
	k["ip rarp-server"] = NewKeyword("ip rarp-server", "To enable the router to act as a Reverse Address Resolution Protocol (RARP) server, use the ip rarp-server command in interface configuration mode. To restore the interface to the default of no RARP server support, use the no form of this command. Disabled Interface configuration This feature makes diskless booting of clients possible between network subnets where the client and server are on separate subnets. RARP server support is configurable on a per-interface basis, so that the router does not interfere with RARP traffic on subnets that need no RARP assistance. The Cisco IOS software answers incoming RARP requests only if both of the following two conditions are met: Use the show ip arp EXEC command to display the contents of the IP ARP cache. Sun Microsystems, Inc. makes use of RARP and UDP-based network services to facilitate network-based booting of SunOS on it’s workstations. By bridging RARP packets and using both the ip helper-address interface configuration command and the ip forward-protocol global configuration command, the Cisco IOS software should be able to perform the necessary packet switching to enable booting of Sun workstations across subnets. Unfortunately, some Sun workstations assume that the sender of the RARP response, in this case the router, is the host that the client can contact to TFTP load the bootstrap image. This causes the workstations to fail to boot. By using the ip rarp-server command, the Cisco IOS software can be configured to answer these RARP requests, and the client machine should be able to reach its server by having its TFTP requests forwarded through the router that acts as the RARP server. In the case of RARP responses to Sun workstations attempting to diskless boot, the IP address specified in the ip rarp-server interface configuration command should be the IP address of the TFTP server. In addition to configuring RARP service, the Cisco IOS software must be configured to forward UDP-based Sun portmapper requests to completely support diskless booting of Sun workstations. This can be accomplished using configuration commands of the following form: RFC 903 documents the RARP.", "ip rarp-server ip-address no ip rarp-server ip-address")
	k["ip rcmd domain-lookup"] = NewKeyword("ip rcmd domain-lookup", "To reena ble the basic Domain Name Service (DNS) security check for rcp and rsh, use the ip rcmd domain-lookup command in global configuration mode. T o disable the basic DNS security check for remote copy protocol (rcp) and remote shell protoco (rsh), use the no form of this command. This command has no arguments or keywords. Enabled Global configuration The abbreviation RCMD (remote command) is used to indicate both rsh and rcp. DNS lookup for RCMD is enabled by default (provided general DNS services are enabled on the system using the ip domain-lookup command). The no ip rcmd domain-lookup command is used to disable the DNS lookup for RCMD. The ip rcmd domain-lookup command is used to reenable the DNS lookup for RCMD. DNS lookup for RCMD is performed as a basic security check. This check is performed using a host authentication process. When enabled, the system records the address of the requesting client. That address is mapped to a host name using DNS. Then a DNS request is made for the IP address for that host name. The IP address received is then checked against the original requesting address. If the address does not match with any of the addresses received from DNS, the RCMD request will not be serviced. This reverse lookup is intended to help protect against spoofing. However, please note that the process only confirms that the IP address is a valid “routable” address; it is still possible for a hacker to spoof the valid IP address of a known host. The DNS lookup is done after the TCP handshake but before the router (which is acting as a rsh/rcp server) sends any data to the remote client. The no ip rcmd domain-lookup will turn off DNS lookups for rsh and rcp only. The no ip domain-lookup command takes precedence over the ip rcmd domain-lookup command. This means that if the no ip domain-lookup command is in the current configuration, DNS will be bypassed for rcp and rsh even if the ip rcmd domain-lookup command is enabled.", "ip rcmd domain-lookup no ip rcmd domain-lookup")
	k["ip rcmd rcp-enable"] = NewKeyword("ip rcmd rcp-enable", "To configure the Cisco IOS software to allow remote users to copy files to and from the router using remote copy protocol (rcp), use the ip rcmd rcp-enable command in global configuration mode. To disable rcp on the device, use the no form of this command. This command has no arguments or keywords. To ensure security, the router is not enabled for rcp by default. Global configuration To allow a remote user to execute rcp commands on the router, you must also create an entry for the remote user in the local authentication database using the ip rcmd remote-host command. The no ip rcmd rcp-enable command does not prohibit a local user from using rcp to copy system images and configuration files to and from the router. To protect against unauthorized users copying the system image or configuration files, the router is not enabled for rcp by default.", "ip rcmd rcp-enable no ip rcmd rcp-enable")
	k["ip rcmd remote-host"] = NewKeyword("ip rcmd remote-host", "To create an entry for the remote user in a local authentication database so that remote users can execute commands on the router using remote shell protocol (rsh) or remote copy protocol (rcp), use the ip rcmd remote-host command in global configuration mode. To remove an entry for a remote user from the local authentication database, use the no form of this command. No entries are in the local authentication database. Global configuration A TCP connection to a router is established using an IP address. Using the host name is valid only when you are initiating an rcp or rsh command from a local router. The host name is converted to an IP address using DNS or host-name aliasing. To allow a remote user to execute rcp or rsh commands on a local router, you must create an entry for the remote user in the local authentication database. You must also enable the router to act as an rsh or rcp server. To enable the router to act as an rsh server, issue the ip rcmd rsh-enable command. To enable the router to act as an rcp server, issue the ip rcmd rcp-enable command.The router cannot act as a server for either of these protocols unless you explicitly enable the capacity. A local authentication database, which is similar to a UNIX .rhosts file, is used to enforce security on the router through access control. Each entry that you configure in the authentication database identifies the local user, the remote host, and the remote user. To permit a remote user of rsh to execute commands in privileged EXEC mode or to permit a remote user of rcp to copy files to the router, specify the enable keyword and level. For information on the enable level, refer to the privilege level global configuration command in the Release 12.2 Cisco IOS Security Command Reference. An entry that you configure in the authentication database differs from an entry in a UNIX .rhosts file in the following aspect. Because the .rhosts file on a UNIX system resides in the home directory of a local user account, an entry in a UNIX .rhosts file need not include the local username; the local username is determined from the user account. To provide equivalent support on a router, specify the local username along with the remote host and remote username in each authentication database entry that you configure. For a remote user to be able to execute commands on the router in its capacity as a server, the local username, host address or name, and remote username sent with the remote client request must match values configured in an entry in the local authentication file. A remote client host should be registered with DNS. The Cisco IOS software uses DNS to authenticate the remote host’s name and address. Because DNS can return several valid IP addresses for a host name, the Cisco IOS software checks the address of the requesting client against all of the IP addresses for the named host returned by DNS. If the address sent by the requester is considered invalid, that is, it does not match any address listed with DNS for the host name, then the software will reject the remote-command execution request. Note that if no DNS servers are configured for the router, then that device cannot authenticate the host in this manner. In this case, the Cisco IOS software sends a broadcast request to attempt to gain access to DNS services on another server. If DNS services are not available, you must use the no ip domain-lookup command to disable the attempt to gain access to a DNS server by sending a broadcast request. If DNS services are not available and, therefore, you bypass the DNS security check, the software will accept the request to remotely execute a command only if all three values sent with the request match exactly the values configured for an entry in the local authentication file.", "ip rcmd remote-host local-username {ip-address | host-name} remote-username [enable [level] ] no ip rcmd remote-host local-username {ip-address | host-name} remote-username [enable [level] ]")
	k["ip rcmd remote-username"] = NewKeyword("ip rcmd remote-username", "To configure the remote username to be used when requesting a remote copy using remote copy protocol (rcp), use the ip rcmd remote-username command in global configuration mode . To remove from the configuration the remote username, use the no form of this command. If you do not issue this command, the Cisco IOS software sends the remote username associated with the current tty process, if that name is valid, for rcp copy commands. For example, if the user is connected to the router through Telnet and the user was authenticated through the username command, then the software sends that username as the remote username. If the username for the current tty process is not valid, the Cisco IOS software sends the host name as the remote username. For rcp boot commands, the Cisco IOS software sends the access server host name by default. Global configuration The rcp protocol requires that a client send the remote username on an rcp request to the server. Use this command to specify the remote username to be sent to the server for an rcp copy request. If the server has a directory structure, as do UNIX systems, all files and images to be copied are searched for or written relative to the directory of the remote user’s account.", "ip rcmd remote-username username no ip rcmd remote-username username")
	k["ip rcmd rsh-enable"] = NewKeyword("ip rcmd rsh-enable", "To configure the router to allow remote users to execute commands on it using remote shell protocol (rsh), use the ip rcmd rsh-enable command in global configuration mode. To disable a router that is enabled for rsh, use the no form of this command. This command has no arguments or keywords. To ensure security, the router is not enabled for rsh by default. Global configuration rsh, used as a client process, gives users the ability to remotely get router information (such as status) without the need to connect into the router and then disconnect. This is valuable when looking at many statistics on many different routers. Use this command to enable the router to receive rsh requests from remote users. In addition to issuing this command, you must create an entry for the remote user in the local authentication database to allow a remote user to execute rsh commands on the router. The no ip rcmd rsh-enable command does not prohibit a local user of the router from executing a command on other routers and UNIX hosts on the network using rsh. The no form of this command only disables remote access to rsh on the router.", "ip rcmd rsh-enable no ip rcmd rsh-enable")
	k["ip rcmd source-interface"] = NewKeyword("ip rcmd source-interface", "To force remote copy protocol (rcp) or remote shell protocol (rsh) to use the IP address of a specified interface for all outgoing rcp/rsh communication packets, use the ip rcmd source-interface command in global configuration mode. To disable a previously configured ip rcmd source-interface command, use the no form of this command. The address of the interface closest to the destination is used as the source interface for rcp/rsh communications. Global configuration If this command is not used, or if the interface specified in this command is not available (not up), the Cisco IOS software uses the address of the interface closest to the destination as the source address. Use this command to force the system to tag all outgoing rcp/rsh packets with the IP address associated with the specified interface. This address is used as the source address as long as the interface is in the up state. This command is especially useful in cases where the router has many interfaces, and you want to ensure that all rcp and/or rsh packets from this router have the same source IP address. A consistent address is preferred so that the other end of the connection (the rcp/rsh server or client) can maintain a single session. The other benefit of a consistent address is that an access list can be configured on the remote device. The specified interface must have an IP address associated with it. If the specified interface does not have an IP address or is in a down state, then rcp/rsh reverts to the default. To avoid this, add an IP address to the subinterface or bring the interface to the up state.", "ip rcmd source-interface interface-id no ip rcmd source-interface interface-id")
	k["ip telnet source-interface"] = NewKeyword("ip telnet source-interface", "To specify the IP address of an interface as the source address for Telnet connections, use the ip telnet source-interface command in global configuration mode. To reset the source address to the default for each connection, use the no form of this command. The address of the closest interface to the destination is the source address. Global configuration Use this command to set the IP address of an interface as the source for all Telnet connections. If the specified interface is not up, the Cisco IOS software selects the address of the interface closest to the destination as the source address.", "ip telnet source-interface interface no ip telnet source-interface")
	k["ip tftp blocksize"] = NewKeyword("ip tftp blocksize", "To negotiate a transfer TFTP blocksize, use the ip tftp blocksize command in global configuration mode. To disable this configuration, use the no form of this command. The default TFTP blocksize is 512 bytes. Global configuration (config)", "ip tftp blocksize bytes no ip tftp blocksize")
	k["ip tftp boot-interface"] = NewKeyword("ip tftp boot-interface", "To use an interface for TFTP booting, use the ip tftp boot-interface command in global configuration mode. To disable this configuration, use the no form of this command. No interface is used for TFTP booting. Global configuration (config)", "ip tftp boot-interface type number no ip tftp boot-interface")
	k["ip tftp min-timeout"] = NewKeyword("ip tftp min-timeout", "To specify the minimum timeout period for retransmission of data using TFTP, use the ip tftp min-timeout command in global configuration mode. To disable, use the no form of this command. The default minimum timeout period for retransmission of data is 4 seconds. Global configuration (config)", "ip tftp min-timeout seconds no ip tftp min-timeout")
	k["ip tftp source-interface"] = NewKeyword("ip tftp source-interface", "To specify the IP address of an interface as the source address for TFTP connections, use the ip tftp source-interface command in global configuration mode. To return to the default, use the no form of this command. The address of the closest interface to the destination is selected as the source address. Global configuration (config) Use this command to set the IP address of an interface as the source for all TFTP connections. If the specified interface is not up, the Cisco IOS software selects the address of the interface closest to the destination as the source address. In Cisco IOS 12.3(6) and later releases, TFTP is VRF-aware, which means that TFTP transfer is supported across an interface within a Virtual Private Network (VPN) routing and forwarding (VRF) instance. To specify a VRF as a source for TFTP connections, the VRF must be associated with the same interface that you configure with the ip tftp source-interface command. In this configuration, TFTP looks for the destination IP address for file transfer in the specified VRF table.", "ip tftp source-interface interface-type interface-number no ip tftp source-interface")
	k["ip wccp web-cache accelerated"] = NewKeyword("ip wccp web-cache accelerated", "To enable the hardware acceleration for WCCP version 1, use the ip wccp web-cache accelerated command in global configuration mode. To disable hardware acceleration, use the no form of this command. When this command is not configured, hardware acceleration for WCCPv1 is not enabled. Global configuration (config) The group-address group-address option requires a multicast address that is used by the router to determine which cache engine should receive redirected messages. This option instructs the router to use the specified multicast IP address to coalesce the “I See You” responses for the “Here I Am” messages that it has received on this group address. In addition, the response is sent to the group address. The default is for no group-address to be configured, so that all “Here I Am” messages are responded to with a unicast reply. The redirect-list access-list option instructs the router to use an access list to control the traffic that is redirected to the cache engines of the service group that is specified by the service-name given. The access-list argument specifies either a number from 1 to 99 to represent a standard or extended access list number, or a name to represent a named standard or extended access list. The access list itself specifies the traffic that is permitted to be redirected. The default is for no redirect-list to be configured (all traffic is redirected). The group-list access-list option instructs the router to use an access list to control the cache engines that are allowed to participate in the specified service group. The access-list argument specifies either a number from 1 to 99 to represent a standard access list number, or a name to represent a named standard access list. The access list specifies which cache engines are permitted to participate in the service group. The default is for no group-list to be configured, so that all cache engines may participate in the service group. The password can be up to seven characters. When you designate a password, the messages that are not accepted by the authentication are discarded. The password name is combined with the HMAC MD5 value to create security for the connection between the router and the cache engine.", "ip wccp web-cache accelerated [ [group-address groupaddress] | [redirect-list access-list] | [group-list access-list] | [password password]] no ip wccp web-cache accelerated")
	k["length"] = NewKeyword("length", "To set the terminal screen length, use the length command in line configuration mode. To restore the default value, use the no form of this command. Screen length of 24 lines Line configuration The Cisco IOS software uses the value of this command to determine when to pause during multiple-screen output. Not all commands recognize the configured screen length. For example, the show terminal command assumes a screen length of 24 lines or more.", "length screen-length no length")
	k["load-interval"] = NewKeyword("load-interval", "To change the length of time for which data is used to compute load statistics, use the load-interval command in interface configuration, Frame Relay DLCI configuration, or template configuration modes. To revert to the default setting, use the no form of this command. Enabled Interface configuration Frame Relay DLCI configuration Template configuration (config-template) To make computations more reactive to short bursts of traffic, you can shorten the length of time over which load averages are computed. If the load interval is set to 30 seconds, new data is used for load calculations over a 30-second period. This data is used to compute load statistics, including the input rate in bits and packets per second, the output rate in bits and packets per second, the load, and reliability. Load data is gathered every five seconds. This data is used for a weighted-average calculation in which recent load data has more weight in the computation than older load data. If the load interval is set to 30 seconds, the average is computed for the last 30 seconds of load data. If you change the calculation interval from the default of five minutes to a shorter period of time, the input and output statistics that are displayed by the show interface command or the show frame-relay pvc command will be more current and will be based on more nearly instantaneous data, rather than reflecting the average load over a longer period of time. This command is often used for dial backup purposes to increase or decrease the likelihood of implementation of a backup interface, but it can be used on any interface.", "load-interval seconds no load-interval seconds")
	k["location"] = NewKeyword("location", "To provide a description of the location of a serial device, use the location command in line configuration mode. To remove the description, use the no form of this command. A location description is not provided. Line configuration (config-line) The location command enters information about the device location and status. Use the show users all EXEC command to display the location information.", "location text no location")
	k["lockable"] = NewKeyword("lockable", "To enable use of the lock EXEC command, use the lockable command in line configuration mode. To reinstate the default (the terminal session cannot be locked), use the no form of this command. This command has no arguments or keywords. Sessions on the line are not lockable (the lock EXEC command has no effect). Line configuration This command enables use of temporary terminal locking, which is executed using the lock EXEC command. Terminal locking allows a user keep the current session open while preventing access by other users.", "lockable no lockable")
	k["log config"] = NewKeyword("log config", "To enter configuration change logger configuration mode, use the log config command in archive configuration mode. This command has no arguments or keywords. Configuration change logger configuration mode is not entered. Archive configuration (config-archive)", "log config")
	k["logging buffered"] = NewKeyword("logging buffered", "To enable system message logging to a local buffer, use the logging buffered command in global configuration mode. To cancel the use of the buffer, use the no form of this command. To return the buffer size to its default value, use the default form of this command. Varies by platform. For most platforms, logging to the buffer is disabled by default. This command copies logging messages to an internal buffer. The buffer is circular in nature, so newer messages overwrite older messages after the buffer is filled. Specifying a severity-level causes messages at that level and numerically lower levels to be logged in an internal buffer. The optional discriminator keyword and discriminator-name argument provide another layer of filtering that you can use to control the type and number of syslog messages that you want to receive. When you resize the logging buffer, the existing buffer is freed and a new buffer is allocated. To prevent the router from running out of memory, do not make the buffer size too large. You can use the show memory EXEC command to view the free processor memory on the router; however, the memory value shown is the maximum available and should not be approached. The default logging buffered command resets the buffer size to the default for the platform. To display messages that are logged in the buffer, use the show logging command. The first message displayed is the oldest message in the buffer. The show logging command displays the addresses and levels associated with the current logging setup and other logging statistics. The table below shows a list of levels and corresponding syslog definitions.", "logging buffered [discriminator discriminator-name] [buffer-size] [severity-level] no logging buffered default logging buffered")
	k["logging buginf"] = NewKeyword("logging buginf", "To allow debug messages to be generated for the standard system logging buffer, use the logging buginf command in global configuration mode. To disable the logging for debugging functionality, use the no form of this command. This command has no arguments or keywords. Debug messages are not suppressed. Global configuration (config) The no logging buginf command is used to avoid a situation where a large amount of debug messages might overload the processor (CPU hog condition). This condition differs from the use of the undebug all command wherein all debugging calls are disabled in the Cisco IOS software. No debug reporting is available, even if debugging is enabled. Note that even though debugging has been completely disabled in the system, other message reporting, including error reporting, is still available.", "logging buginf no logging buginf")
	k["logging enable"] = NewKeyword("logging enable", "To enable the logging of configuration changes, use the logging enable command in configuration change logger configuration mode. To disable the logging of configuration changes, use the no form of this command. This command has no arguments or keywords. Configuration change logging is disabled. Configuration change logger configuration (config-archive-log-config) Use this command if you want to log configuration changes. If you disable configuration logging, all configuration log records that were collected are purged.", "logging enable no logging enable")
	k["logging esm config"] = NewKeyword("logging esm config", "To permit configuration changes from Embedded Syslog Manager (ESM) filters, use the logging esm config command in global configuration mode. To disable the configuration, use the no form of this command. This command has no arguments or keywords. ESM filters are enabled. Global configuration (config) You can use the no logging esm config command to disallow configuration changes from ESM filters.", "logging esm config no logging esm config")
	k["logging event bundle-status"] = NewKeyword("logging event bundle-status", "To enable message bundling, use the logging event bundle-status command in interface configuration mode. To disable message bundling, use the no form of this command. Message bundling does not occur. Global configuration The logging event bundle-status command is not applicable on Port Channel or Ether-Channel interfaces.", "logging event bundle-status no logging event bundle-status")
	k["logging event link-status (global configuration)"] = NewKeyword("logging event link-status (global configuration)", "To change the default or set the link-status event messaging during system initialization, use the logging event link-status command in global configuration mode. To disable the link-status event messaging, use the no form of this command. Interface state-change messages are not sent. Global configuration You do not have to enter the logging event link-status boot command to enable link-status messaging during system initialization. The logging event link-status default command logs system messages even during system initialization. If you enter both the logging event link-status default and the no logging event link-status boot commands, the interface state-change events are logged after all modules in the Cisco 7600 series router come online after system initialization. The logging event link-status default and the no logging event link-status boot commands are saved and retained in the running configuration of the system. When both the logging event link-status default and the no logging event link-status boot commands are present in the running configuration and you want to display the interface state-change messages during system initialization, enter the logging event link-status boot command.", "logging event link-status {default | boot} no logging event link-status {default | boot}")
	k["logging event link-status (interface configuration)"] = NewKeyword("logging event link-status (interface configuration)", "To enable link-status event messaging on an interface, use the logging event link-status command in interface configuration mode. To disable link-status event messaging, use the no form of this command. Interface state-change messages are not sent. Interface configuration (config-if) To enable system logging of interface state-change events on a specific interface, enter the logging event link-status command.", "logging event link-status [bchan | dchan | nfas] no logging event link-status [bchan | dchan | nfas]")
	k["logging event subif-link-status"] = NewKeyword("logging event subif-link-status", "To enable the link-status event messaging on a subinterface, use the logging event subif-link-status command in interface configuration mode. To disable the link-status event messaging on a subinterface, use the no form of this command. This command has no arguments or keywords. Subinterface state-change messages are not sent. Interface configuration This command is not supported on Cisco 7600 series routers that are configured with a Supervisor Engine 720. To enable system logging of interface state-change events on a specific subinterface, enter the logging event subif-link-status command. To enable system logging of interface state-change events on a specific interface, enter the logging event link-status command. To enable system logging of interface state-change events on all interfaces in the system, enter the logging event link-status command.", "logging event subif-link-status no logging event subif-link-status")
	k["logging event trunk-status"] = NewKeyword("logging event trunk-status", "To enable trunk status messaging, use the logging event trunk-status command in interface configuration mode. To disable trunk status messaging, use the no form of this command. This command has no keywords or variables. This command has no default settings. Interface configuration mode The logging event bundle-status command is not applicable on Port Channel or Ether-Channel interfaces.", "logging event trunk-status no logging event trunk-status")
	k["logging reload"] = NewKeyword("logging reload", "To set the reload logging level, use the logging reload command in global configuration mode. To disable the reload logging, use the no form of this command. The logging reload message limit is 1000 notifications. Global configuration (config) The default setting is recommended. Setting the message-limit too low may result in losing important messages during reload. If the logging reload command is not enabled, logging is turned off during reload.", "logging reload [message-limit number] [severity-level | alerts | critical | debugging | emergencies | errors | informational | notifications | warnings] no logging reload")
	k["logging ip access-list cache (global configuration)"] = NewKeyword("logging ip access-list cache (global configuration)", "To configure the Optimized ACL Logging (OAL) parameters, use the logging ip access-list cache command in global configuration mode. To return to the default settings, use the no form of this command. The defaults are as follows: Global configuration This command is supported on Cisco 7600 series routers that are configured with a Supervisor Engine 720 only. OAL is supported on IPv4 unicast traffic only. You cannot configure OAL and VACL capture on the same chassis. OAL and VACL capture are incompatible. With OAL configured, use SPAN to capture traffic. If the entry is inactive for the duration that is specified in the update-interval seconds command, th e entry is removed from the cache. If you enter the no logging ip access-list cache command without keywords, all the parameters are returned to the default values. You must set ICMP unreachable rate limiting to 0 if the OAL is configured to log denied packets. When enabling the IP \"too short\" check using the mls verify ip length minimum command, valid IP packets with with an IP protocol field of ICMP(1), IGMP(2), IP(4), TCP(6), UDP(17), IPv6(41), GRE(47), or SIPP-ESP(50) will be hardware switched. All other IP protocol fields are software switched.", "logging ip access-list cache {entries entries | interval seconds | rate-limit pps | threshold packets} no logging ip access-list cache [entries | interval | rate-limit | threshold]")
	k["logging ip access-list cache (interface configuration)"] = NewKeyword("logging ip access-list cache (interface configuration)", "To enable an Optimized ACL Logging (OAL)-logging cache on an interface that is based on direction, use the logging ip access-list cache command in interface configuration mode. To disable OAL, use the no form of this command. Disabled Interface configuration This command is supported on Cisco 7600 series routers that are configured with a Supervisor Engine 720 only. This command is supported on traffic that matches the log keyword in the applied ACL. You must set ICMP unreachable rate limiting to 0 if the OAL is configured to log denied packets. On systems that are configured with a PFC3A, support for the egress direction on tunnel interfaces is not supported. OAL is supported on IPv4 unicast traffic only. You cannot configure OAL and VACL capture on the same chassis. OAL and VACL capture are incompatible. With OAL configured, use SPAN to capture traffic. If the entry is inactive for the duration that is specified in the update-interval seconds command, th e entry is removed from the cache. If you enter the no logging ip access-list cache command without keywords, all the parameters are returned to the default values. When enabling the IP \"too short\" check using the mls verify ip length minimum command, valid IP packets with with an IP protocol field of ICMP(1), IGMP(2), IP(4), TCP(6), UDP(17), IPv6(41), GRE(47), or SIPP-ESP(50) will be hardware switched. All other IP protocol fields are software switched.", "logging ip access-list cache [in | out] no logging ip access-list cache")
	k["logging persistent (config-archive-log-cfg)"] = NewKeyword("logging persistent (config-archive-log-cfg)", "To enable the configuration logging persistent feature and to select how the configuration commands are to be saved to the Cisco IOS secure file system, use the logging persistent command in the log config submode of archive configuration mode. To disable this capability, use the no form of this command. The configuration commands are not saved to the Cisco IOS secure file system. Archive configuration mode, log config (configuration-change logger) submode (config-archive-log-cfg)# When you use the manual keyword, you must save each configuration command manually to the Cisco IOS secure file system. To do this, you must use the archive log config persistent save command.", "logging persistent {auto | manual} no logging persistent {auto | manual}")
	k["logging persistent reload (config-archive-log-cfg)"] = NewKeyword("logging persistent reload (config-archive-log-cfg)", "To sequentially apply the configuration commands saved in the configuration logger database (since the last write memory command) to the running-config file after a reload, use the logging persistent reload command in configuration change logger configuration mode in archive configuration mode. To disable this capability, use the no form of this command. This command has no arguments or keywords. The configuration commands saved in the configuration logger database are not applied to the running-config file. Archive config mode; log config (configuration change logger) submode (config-archive-log-cfg)# Use the logging persistent reload command when you want changed configuration commands to take effect on the next reload of the router.", "logging persistent reload no logging persistent reload")
	k["logging size"] = NewKeyword("logging size", "To specify the maximum number of entries retained in the configuration log, use the logging size command in configuration change logger configuration mode. To reset the default value, use the no form of this command. 100 entries Configuration change logger configuration (config-archive-log-config) When the configuration log is full, the oldest log entry is removed every time a new entry is added.", "logging size entries no logging size")
	k["logging synchronous"] = NewKeyword("logging synchronous", "To synchronize unsolicited messages and debug output with solicited Cisco IOS software output and prompts for a specific console port line, auxiliary port line, or vty, use the logging synchronous command in line configuration mode. To disable synchronization of unsolicited messages and debug output, use the no form of this command. This command is disabled. If you do not specify a severity level, the default value of 2 is assumed. If you do not specify the maximum number of buffers to be queued, the default value of 20 is assumed. Line configuration When synchronous logging of unsolicited messages and debug output is turned on, unsolicited Cisco IOS software output is displayed on the console or printed after solicited Cisco IOS software output is displayed or printed. This keeps unsolicited messages and debug output from being interspersed with solicited software output and prompts. When this command is enabled, unsolicited messages and debug output are displayed on a separate line than user input. After the unsolicited messages are displayed, the CLI returns to the user prompt. When specifying a severity level number, consider that for the logging system, low numbers indicate greater severity and high numbers indicate lesser severity. When a message queue limit of a terminal line is reached, new messages are dropped from the line, although these messages might be displayed on other lines. If messages are dropped, the notice “ %SYS-3-MSGLOST number-of-messages due to overflow” follows any messages that are displayed. This notice is displayed only on the terminal that lost the messages. It is not sent to any other lines, any logging servers, or the logging buffer.", "logging synchronous [level severity-level | all] [limit number-of-lines] no logging synchronous [level severity-level | all] [limit number-of-lines]")
	k["logging system"] = NewKeyword("logging system", "To enable System Event Archive (SEA) logging, use the logging system command in global configuration mode. To disable SEA logging, use the no form of this command. By default, SEA logging feature is enabled, and the events are logged to a file on a persistent storage device (bootflash: or disk:). Global configuration (config) SEA is supported on switches that have a Supervisor Engine 32 or Supervisor Engine 720 with a compact flash adapter and a Compact Flash card (WS-CF-UPG\u003D for Supervisor Engine 720). To stop SEA logging to a specified disk, use the default logging system command. For documentation of the configuration tasks associated with this feature, see the chapter “Configuring the System Event Archive” in the Catalyst 6500 Release 12.2SX Software Configuration Guide . Cisco Universal Broadband Router 100112 The SEA feature is used to address the deficiencies of the debug trace and system console. Support for SEA feature was introduced on Cisco uBR10012 Router in the Cisco IOS Release 12.2(33)SCC. Use the logging system disk command to change the location of the disk used to store the sea_log.dat file.", "logging system [disk name] no logging system")
	k["logout-warning"] = NewKeyword("logout-warning", "To warn users of an impending forced timeout, use the logout-warning command in line configuration mode. To restore the default, use the no form of this command. No warning is sent to the user. Line configuration This command notifies the user of an impending forced timeout (set using the absolute-timeout command).", "logout-warning [seconds] logout-warning")
	k["macro (global configuration)"] = NewKeyword("macro (global configuration)", "To create a global command macro, use the macro command in global configuration mode. To remove the macro, use the no form of this command. This command has no default setting. Global configuration (config) You can enter up to three keyword pairs using the macro global trace command. You can enter the macro global description command on the switch stack or on a standalone switch. Use the description text keyword and argument to associate the comment text, or the macro name with a switch. When multiple macros are applied on a switch, the description text is used from the last applied macro. You can verify the global description settings by using the show parser macro description command. To find the syntax or configuration errors, enter the macro global trace macro-name command to apply and debug the macro. To display a list of any keyword-value pairs defined in the macro, enter the macro global apply macro-name ? command. You can delete a global macro-applied configuration on a switch only by entering the no version of each command that is in the macro. Keyword matching is case sensitive. When a macro is applied on the commands, all matching occurrences of keywords are replaced with the corresponding values. The no form of the macro name command deletes only the macro definition. It does not affect the configuration of the interfaces on which the macro is already applied.", "macro {global {apply macro-name | description text | trace macro-name [keyword-to-value] value-first-keyword [keyword-to-value] value-second-keyword [keyword-to-value] value-third-keyword [keyword-to-value] } | name macro-name} no macro {global {apply macro-name | description text | trace macro-name [keyword-to-value] value-first-keyword [keyword-to-value] value-second-keyword [keyword-to-value] value-third-keyword [keyword-to-value] } | name macro-name}")
	k["macro (interface configuration)"] = NewKeyword("macro (interface configuration)", "To create an interface-specific command macro, use the macro command in interface configuration mode. To remove the macro, use the no form of this command. This command has no default setting. Interface configuration (config-if) You can enter up to three keyword changes using the macro trace command. You can enter the macro description command on the switch stack or on a standalone switch. Use the description text keyword and argument to associate comment text, or the macro name, with a switch. When multiple macros are applied on a switch, the description text will be from the last applied macro. You can verify the description settings by entering the show parser macro description command. To find any syntax or configuration errors, enter the macro trace macro-name command to apply and debug the macro. To display a list of any keyword-value pairs defined in the macro, enter the macro apply macro-name ? command. To successfully apply the macro, you must enter any required keyword-value pairs. Keyword matching is case sensitive. In the commands that the macro applies, all matching occurrences of keywords are replaced with the corresponding values. You can delete all configuration on an interface by entering the default interface interface interface configuration command.", "macro {apply macro-name | description text | trace macro-name [keyword-to-value] value-first-keyword [keyword-to-value] value-second-keyword [keyword-to-value] value-third-keyword [keyword-to-value] } no macro {apply macro-name | description text | trace macro-name [keyword-to-value] value-first-keyword [keyword-to-value] value-second-keyword [keyword-to-value] value-third-keyword [keyword-to-value] }")
	k["maximum"] = NewKeyword("maximum", "To set the maximum number of archive files of the running configuration to be saved in the Cisco configuration archive, use the maximum command in archive configuration mode. To reset this command to its default, use the no form of this command. By default, a maximum of 10 archive files of the running configuration are saved in the Cisco configuration archive. Archive configuration (config-archive) After the maximum number of files are saved in the Cisco configuration archive, the oldest file is automatically deleted when the next, most recent file is saved.", "maximum number no maximum number")
	k["memory cache error-recovery"] = NewKeyword("memory cache error-recovery", "To trace error recovery in memory using caches, use the memory cache error-recovery command in global configuration mode. To disable the memory cache error recovery mechanisms, use the no form of this command. Memory cache error recovery mechanisms are not enabled. Global configuration (config)", "memory cache error-recovery {L1 | L2 | L3} {data | inst} no memory cache error-recovery {L1 | L2 | L3} {data | inst}")
	k["memory cache error-recovery options"] = NewKeyword("memory cache error-recovery options", "To trace error recovery in memory using caches through set options, use the memory cache error-recovery options command in global configuration mode. To disable the set memory cache error recovery mechanisms, use the no form of this command. Memory cache error recovery mechanisms are not enabled. Global configuration (config)", "memory cache error-recovery options {abort-if-same-content | blocking-mode | max-recoveries value | nvram-report | parity-check | window seconds} no memory cache error-recovery options {abort-if-same-content | blocking-mode | max-recoveries value | nvram-report | parity-check | window seconds}")
	k["memory free low-watermark"] = NewKeyword("memory free low-watermark", "To configure a router to issue system logging message notifications when available memory falls below a specified threshold, use the memory free low-watermark command in global configuration mode. To disable memory threshold notifications, use the no form of this command. Memory threshold notifications are disabled. Global configuration Using this command, you can configure a router to issue a system logging message each time available free memory falls below a specified threshold (“low-watermark”). Once available free memory rises to 5 percent above the threshold, another notification message is generated.", "memory free low-watermark {processor threshold | io threshold} no memory free low-watermark")
	k["memory lite"] = NewKeyword("memory lite", "To enable the memory allocation lite (malloc_lite) feature, use the memory lite command in global configuration mode. To disable this feature, use the no form of this command. This command has no arguments or keywords. This command is enabled by default. Global configuration The malloc_lite feature was implemented to avoid excessive memory allocation overhead for situations where less than 128 bytes were required. This feature is supported for processor memory pools only. The malloc_lite feature is enabled by default. If the malloc_lite feature is disabled using the no memory lite command, you can re-enable the feature by entering the memory lite command.", "memory lite no memory lite")
	k["memory reserve"] = NewKeyword("memory reserve", "To reserve a specified amount of memory in kilobytes for console access and critical notifications, use the memory reserve command in global configuration mode. To disable the configuration, use the no form of this command. Global configuration (config) 256 KB is reserved for console memory access. 100 KB is reserved for cricial memory access. The memory reserve console command reserves enough memory to ensure console access to a Cisco IOS device for administrative and troubleshooting purposes. This feature is especially beneficial when the device runs low on memory. The memory reserve critical command reserves the specified amount of memory in kilobytes so that the router can issue critical notifications. The amount of memory reserved for critical notifications cannot exceed 25 percent of the total available memory.", "Syntax for Releases 15.0(1)M and 12.2(33)SRC and Later Releases memory reserve {console size | critical [total-size] } no memory reserve {console | critical} Syntax for Releases 12.2(33)SXI, Cisco IOS XE Release 2.1 and Later Releases memory reserve critical [total-size] no memory reserve critical")
	k["memory reserve critical"] = NewKeyword("memory reserve critical", "To configure the size of the memory region to be used for critical notifications (system logging messages), use the memory reserve critical command in global configuration mode. To disable the reservation of memory for critical notifications, use the no form of this command. 100 kilobytes of memory is reserved for the logging process. Global configuration (config) This command reserves a region of memory on the router so that, when system resources are overloaded, the router retains enough memory to issue critical system logging messages.", "memory reserve critical kilobytes no memory reserve critical")
	k["memory sanity"] = NewKeyword("memory sanity", "To perform a “sanity check” for corruption in buffers and queues, use the memory sanity command in global configuration mode. To disable this feature, use the no form of this command. This command is not enabled by default. If the buffer or queue keyword is not specified, a sanity check will be performed on all buffers and queues. Global configuration When the memory sanity buffer command is enabled, a sanity check is performed on buffers when a packet buffer is allocated or when a packet buffer is returned to the buffer pool. This command also time-stamps the buffer, which may be useful when tracking the age of a buffer. The memory sanity command can be saved in the startup configuration file and, therefore, it is not necessary to reconfigure this command each time the router is reloaded. Like the scheduler heapcheck process memory command, the memory sanity command can check for corruption in the I/O memory block. Enabling the memory sanity command may result in slight router performance degradation.", "memory sanity [buffer | queue | all] no memory sanity")
	k["memory scan"] = NewKeyword("memory scan", "To enable the Memory Scan feature, use the memory scan command in global configuration mode. To restore the router configuration to the default, use the no form of this command. This command has no arguments or keywords. This command is disabled by default. Global configuration The Memory Scan feature adds a low-priority background process that searches all installed dynamic random-access memory (DRAM) for possible parity errors. If errors are found in memory areas that are not in use, this feature attempts to scrub (remove) the errors. The time to complete one memory scan and scrub cycle can range from 10 minutes to several hours, depending on the amount of installed memory. The impact of the Memory Scan feature on the central processing unit (CPU) is minimal. To view the status of the memory scan feature on your router, use the show memory scan command in EXEC mode.", "memory scan no memory scan")
	k["memory-size iomem"] = NewKeyword("memory-size iomem", "To reallocate the percentage of DRAM to use for I/O memory and processor memory, use the memory-size iomem command in global configuration mode. To revert to the default memory allocation, use the no form of this command. The default memory allocation is 25 percent of the DRAM to I/O memory and 75 percent of the DRAM to processor memory. Global configuration (config) When you specify the percentage of I/O memory in the command line, the processor memory automatically acquires the remaining percentage of the DRAM memory.", "memory-size iomem i/o-memory-percentage no memory-size iomem")
	k["menu menu-name single-space"] = NewKeyword("menu menu-name single-space", "To display menu items single-spaced rather than double-spaced, use the menu \u003Cmenu-name\u003E single-space command in global configuration mode. Enabled for menus with more than nine items; disabled for menus with nine or fewer items. Global configuration When more than nine menu items are defined, the menu is displayed single-spaced. To configure the menus with nine or fewer items to display single-spaced, use this command.", "menu menu-name single-space")
	k["menu clear-screen"] = NewKeyword("menu clear-screen", "To clear the terminal screen before displaying a menu, use the menu clear-screen command in global configuration mode. Disabled Global configuration This command uses a terminal-independent mechanism based on termcap entries defined in the router and the configured terminal type for the user. This command allows the same menu to be used on multiple types of terminals instead of having terminal-specific strings embedded within menu titles. If the termcap entry does not contain a clear string, the menu system enters 24 new lines, causing all existing text to scroll off the top of the terminal screen.", "menu clear-screen menu-name clear-screen")
	k["menu command"] = NewKeyword("menu command", "To specify underlying commands for user menus, use the menu command command in global configuration mode. To return to default settings, use the no form of this command. This command is disabled by default. Global configuration (config) Use this command to assign actions to items in a menu. Use the menu text global configuration command to assign text to items. These commands must use the same menu name and menu selection key. The menu command command has a special keyword for the command argument, menu-exit , that is available only within menus. It is used to exit a submenu and return to the previous menu level, or to exit the menu altogether and return to the EXEC command prompt. You can create submenus that are opened by selecting entries in another menu. Use the menu EXEC command as the command for the submenu item. When a menu allows connections (their normal use), the command for an entry activating the connection should contain a resume command, or the line should be configured to prevent users from escaping their sessions with the escape-char none command. Otherwise, when they escape from a connection and return to the menu, there will be no way to resume the session and it will sit idle until the user logs out. Specifying the resume command as the action that is performed for a selected menu entry permits a user to resume a named connection or connect using the specified name, if there is no active connection by that name. As an option, you can also supply the connect string needed to connect initially. When you do not supply this connect string, the command uses the specified connection name. You can also use the resume or next command, which resumes the next connection in the user’s list of connections. This function allows you to create a single menu entry that steps through all of the user’s connections. When a particular line should always display a menu, that line can be configured with an autocommand line configuration command. Menus can be run on a per-user basis by defining a similar autocommand command for that local username. For more information about the autocommand command, see the Cisco IOS Dial Technologies Configuration Guide.", "menu command menu menu-name command menu-item {command | menu-exit}")
	k["menu default"] = NewKeyword("menu default", "To specify the menu item to use as the default, use the menu default command in global configuration mode. Disabled Global configuration Use this command to specify which menu entry is used when the user presses Enter without specifying an item. The menu entries are defined by the menu command and menu text global configuration commands.", "menu menu-name default menu-item")
	k["menu line-mode"] = NewKeyword("menu line-mode", "To require the user to press Enter after specifying an item, use the menu line-mode command in global configuration mode. Enabled for menus with more than nine items. Disabled for menus with nine or fewer items. Global configuration In a menu of nine or fewer items, you ordinarily select a menu item by entering the item number. In line mode, you select a menu entry by entering the item number and pressing Enter. Line mode allows you to backspace over the selected number and enter another number before pressing Enter to issue the command. This option is activated automatically when more than nine menu items are defined but also can be configured explicitly for menus of nine or fewer items. In order to use strings as keys for items, the menu line-mode command must be configured.", "menu menu-name line-mode")
	k["menu options"] = NewKeyword("menu options", "To set options for items in user menus, use the menu options command in global configuration mode. The menu options are disabled. Global configuration (config) Use the menu command and menu text commands to define a menu entry.", "Cisco IOS Release 10.0, 12.2(33)SRA, 12.2(33)SXI , and Later Releases menu menu-name options menu-item [login] [pause] Cisco IOS XE Release 3.1S and Later Releases menu menu-name options menu-item {login | pause}")
	k["menu prompt"] = NewKeyword("menu prompt", "To specify the prompt for a user menu, use the menu prompt command in global configuration mode. Disabled Global configuration Press Enter after entering the first delimiter. The router will prompt you for the text of the prompt. Enter the text followed by the delimiter, and press Enter. Use the menu command and menu text commands to define the menu selections.", "menu menu-name prompt d prompt d")
	k["menu status-line"] = NewKeyword("menu status-line", "To display a line of status information about the current user at the top of a menu, use the menu status-line command in global configuration mode. Disabled Global configuration This command displays the status information at the top of the screen before the menu title is displayed. This status line includes the router’s host name, the user’s line number, and the current terminal type and keymap type (if any).", "menu menu-name status-line")
	k["menu text"] = NewKeyword("menu text", "To specify th e text of a menu item in a user menu, use the menu text command in global configuration mode. No text appears for the menu item. Global configuration Use this command to assign text to items in a menu. Use the menu command command to assign actions to items. These commands must use the same menu name and menu selection key. You can specify a maximum of 18 items in a menu.", "menu menu-name text menu-item menu-text")
	k["menu title"] = NewKeyword("menu title", "To create a t itle (banner) for a user menu, use the menu title command in global configuration mode. The menu does not have a title. Global configuration The menu title command must use the same menu name used with the menu text and menu command commands used to create a menu. You can position the title of the menu horizontally by preceding the title text with blank characters. You can also add lines of space above and below the title by pressing Enter. Follow the title keyword with one or more blank characters and a delimiting character of your choice. Then enter one or more lines of text, ending the title with the same delimiting character. You cannot use the delimiting character within the text of the message. When you are configuring from a terminal and are attempting to include special control characters, such as a screen-clearing string, you must use Ctrl-V before the special control characters so that they are accepted as part of the title string. The string ^[[H^[[J is an escape string used by many VT100-compatible terminals to clear the screen. To use a special string, you must enter Ctrl-V before each escape character. You also can use the menu clear-screen global configuration command to clear the screen before displaying menus and submenus, instead of embedding a terminal-specific string in the menu title. The menu clear-screen command allows the same menu to be used on different types of terminals.", "menu menu-name title d menu-title d")
	k["microcode (12000)"] = NewKeyword("microcode (12000)", "To load a Cisco IOS software image on a line card from Flash memory or the GRP card on a Cisco 12000 series Gigabit Switch Router (GSR), use the microcode command in global configuration mode. To load the microcode bundled with the GRP system image, use the no form of this command. The default is to load the image from the GRP card (system ). Global configuration In addition to the Cisco IOS image that resides on the GRP card, each line card on a Cisco 12000 series has a Cisco IOS image. When the router is reloaded, the specified image is loaded onto the GRP card and then automatically downloaded to all the line cards. Normally, you want the same Cisco IOS image on the GRP card and all line cards. However, if you want to upgrade a line card with a new version of microcode for testing or to fix a defect, you might need to load a Cisco IOS image that is different from the one on the line card. Additionally, you might need to load a new image on the line card to work around a problem that is affecting only one of the line cards. To load a Cisco IOS image on a line card, first use the copy tftp command to download the Cisco IOS image to a slot on one of the PCMCIA Flash memory cards. Then use the microcode command to download the image to the line card, followed by the microcode reload command to start the image. Immediately after you enter the microcode reload command and press Return, the system reloads all microcode. Global configuration mode remains enabled. After the reloading is complete, enter the exit command to return to the EXEC system prompt. To verify that the correct image is running on the line card, use the execute-on slot slot show version command. For additional information on GSR configuration, refer to the documentation specific to your Cisco IOS software release.", "microcode {oc12-atm | oc12-pos | oc3-pos4} {flash file-id [slot] | system [slot] } no microcode {oc12-atm | oc12-pos | oc3-pos4} [flash file-id [slot] | system [slot] ]")
	k["microcode (7000/7500)"] = NewKeyword("microcode (7000/7500)", "To specify the location of the microcode that you want to download from Flash memory into the writable control store (WCS) on Cisco 7000 series (including RSP based routers) or Cisco 7500 series routers, use the microcode command in global configuration mode. To load the microcode bundled with the system image, use the no form of this command. The default is to load from the microcode bundled in the system image. Global configuration If you do not use the microcode reload command after using the microcode command, the microcode reload command will be written to the configuration file automatically. When using Dual RSPs for simple hardware backup, ensure that the primary and secondary RSP card contain the same microcode image in the same location when the router is to load the interface processor microcode from a Flash file system. Thus, if the secondary RSP becomes the primary, it will be able to find the microcode image and download it to the interface processor.", "microcode interface-type {flash-filesystem:filename [slot] | rom | system [slot] } no microcode interface-type {flash-filesystem:filename [slot] | rom | system [slot] }")
	k["microcode (7200)"] = NewKeyword("microcode (7200)", "To configure a default override for the microcode that is downloaded to the hardware on a Cisco 7200 series router, use the microcode command in global configuration mode. To revert to the default microcode for the current running version of the Cisco IOS software, use the no form of this command. If the default or no form of the command is specified, the driver uses the default microcode for the current running version of the Cisco IOS software. Global configuration If there are any default overrides when the configuration is written, then the microcode reload command will be written to the configuration automatically. This action enables the configured microcode to be downloaded at system startup. The CPA microcode image is preloaded on Flash memory cards for Cisco 7200-series routers for Cisco IOS Release 11.3(3)T and later releases. You may be required to copy a new image to Flash memory when a new microcode image becomes available. For more information on the CPA configuration and maintenance, refer to the “Configuring Cisco Mainframe Channel Connection Adapters” chapter in the Release 12.2 Cisco IOS Bridging and IBM Networking Configuration Guide.", "microcode {ecpa | pcpa} location no microcode {ecpa | pcpa}")
	k["microcode reload (12000)"] = NewKeyword("microcode reload (12000)", "To reload the Cisco IOS image from a line card on Cisco 12000 series routers, use the microcode reload command in global configuration mode. Global configuration In addition to the Cisco IOS image that resides on the GRP card, each line card on Cisco 12000 series routers has a Cisco IOS image. When the router is reloaded, the specified Cisco IOS image is loaded onto the GRP card and automatically downloaded to all the line cards. Normally, you want the same Cisco IOS image on the GRP card and all line cards. However, if you want to upgrade a line card with a new version of microcode for testing or to fix a defect, you might need to load a different Cisco IOS image. Additionally, you might need to load a new image on the line card to work around a problem affecting only one of the line cards. To load a Cisco IOS image on a line card, first use the copy tftp command to download the Cisco IOS image to a slot on one of the PCMCIA Flash memory cards. Then use the microcode command to download the image to the line card, followed by the microcode reload command to start the image. To verify that the correct image is running on the line card, use the execute-on slot slot show version command. For additional information on GSR configuration, refer to the “Observing System Startup and Performing a Basic Configuration” chapter in the Cisco 12000 series installation and configuration guides. The microcode reload (12000) command allows you to issue another command immediately.", "microcode reload [slot-number]")
	k["microcode reload (7000 7500)"] = NewKeyword("microcode reload (7000 7500)", "To reload the processor card on the Cisco 7000 series with RSP7000 or Cisco 7500 series routers, use the microcode reload command in global configuration mode. No default behaviors or values. Global configuration This command reloads the microcode without rebooting the router. Immediately after you enter the microcode reload command, the system reloads all microcode. Global configuration mode remains enabled.", "microcode reload [slot-number]")
	k["mode"] = NewKeyword("mode", "To set the redundancy mode, use the mode command in redundancy configuration mode. Redundancy configuration (config-red) Cisco IOS Release 12.2S and 7600 Series Routers SSO is not supported on Cisco 7600 series routers that are configured with a Supervisor Engine 2. On releases prior to Release 12.2(17d)SXB, single router mode (SRM) with SSO redundancy does not support stateful switchover for multicast traffic. When a switchover occurs, all multicast hardware switching entries are removed and are then re-created and reinstalled in the hardware by the newly active multilayer switch feature card (MSFC). SRM/SSO is supported in the following releases only: Nonstop forwarding (NSF) with SSO redundancy mode supports IPv4. NSF with SSO redundancy mode does not support IPv6, Internetwork Packet Exchange (IPX), and Multiprotocol Label Switching (MPLS). If you have configured MPLS on the Cisco 7600 series routers with redundant supervisor engines, you must configure the Cisco 7600 series router in RPR mode. The switch should not be running in the default mode of SSO. Enter the redundancy command in global configuration mode to enter redundancy configuration mode. You can enter the mode command within redundancy configuration mode. Follow these guidelines when configuring your system for RPR+ mode: The standby supervisor engine reloads on any change of mode and begins to work in the current mode. When you use this command to force the standby supervisor engine to run as a Distributed Forwarding Card (DFC) card, the uplink ports in the standby engine continue to be in use and are not disabled. Cisco IOS Release XE Release 2.5 and ASR 1000 Series Routers For Cisco ASR 1002 and 1004 routers, RRP and stateful switchover can be used to switch between Cisco IOS processes. RPR and SSO need to be configured by the user, however, because a second Cisco IOS process is not available by default on Cisco ASR 1002 and 1004 routers. Enter the redundancy command in global configuration mode to enter redundancy configuration mode. You can enter the mode command within redundancy configuration mode. The Cisco ASR 1006 Router supports a second Route Processor. The second Cisco IOS process can run only on the standby Route Processor. This means that hardware redundancy is available and RPR and SSO do not need to be configured by the user because a second Cisco IOS process is available by default on the Cisco ASR 1006 router. RPR+ mode is not supported on the Cisco ASR 1000 Series Routers. Cisco IOS Release 12.2XNE and 1000 Series Routers Enter the redundancy command in global configuration mode to enter redundancy configuration mode. You can enter the mode command within redundancy configuration mode. RPR mode is not supported on the Cisco 10000 router.", "Syntax for 12.2S Release mode {rpr | rpr-plus | sso} Syntax for Cisco IOS XE Release 2.5 and Later Releases mode {rpr | sso} Syntax for 12.2XNE Release mode sso")
	k["monitor event-trace (global)"] = NewKeyword("monitor event-trace (global)", "To configure event tracing for a specified Cisco IOS software subsystem component, use the monitor event-trace command in global configuration mode. Event tracing is enabled or disabled depending on the software component. Global configuration (config) Use the monitor event-trace command to enable or disable event tracing and to configure event trace parameters for Cisco IOS software subsystem components. The Cisco IOS software allows the subsystem components to define whether support for event tracing is enabled or disabled by default. The command interface for event tracing allows you to change the default two ways: using the monitor event-trace command in privileged EXEC mode or using the monitor event-trace command in global configuration mode. Additionally, default settings do not show up in the configuration file. If the subsystem software enables event tracing by default, the monitor event-trace componentenable command will not show up in the configuration file of the networking device; however, disabling event tracing that has been enabled by default by the subsystem will create a command entry in the configuration file. To determine whether you can enable event tracing on a subsystem, use the monitor event-trace ? command to get a list of software components that support event tracing. To determine whether event tracing is enabled by default for the subsystem, use the show monitor event-trace command to display trace messages. To specify the trace call stack at tracepoints, you must first clear the trace buffer.", "monitor event-trace component {disable | dump-file filename | enable | size number | stacktrace number} timestamps [datetime [localtime] [msec] [show-timezone] | uptime] Cisco 10000 Series Routers monitor event-trace component {disable | dump-file filename | enable | clear | continuous | one-shot}")
	k["monitor pcm-tracer capture-destination"] = NewKeyword("monitor pcm-tracer capture-destination", "To configure a location to save the Pulse Code Modulation (PCM) trace information, use the monitor pcm-tracer capture-destination command in global configuration mode. To disable the configuration, use the no form of this command. The PCM trace information is saved to the NVRAM. Global configuration (config) You can use the monitor pcm-tracer capture-destination command to specify a location to save the PCM trace information. When Cisco IOS software saves the data to network file systems, such as TFTP and FTP, it assumes the location is valid and has write access. After the PCM capture is complete, the router automatically copies the captured contents to the specified location. The filename format at the destination location is as follows: You can identify the dial feature card (DFC) channel from where the PCM is traced using the filename format. Consider the following example: In this example, two files are created for the data corresponding to each DS0s, one for each direction (transmitter and receiver). When the debug pcmtracer command is enabled, the trace data is copied into the following files:", "monitor pcm-tracer capture-destination destination no monitor pcm-tracer capture-destination")
	k["monitor pcm-tracer delayed-start"] = NewKeyword("monitor pcm-tracer delayed-start", "To configure the delay time to start the Pulse Code Modulation (PCM) trace capture, use the monitor pcm-tracer delayed-start command in global configuration mode. To disable the configuration, use the no form of this command. The default delay time is zero. Global configuration (config)", "monitor pcm-tracer delayed-start seconds no monitor pcm-tracer delayed-start")
	k["monitor pcm-tracer profile"] = NewKeyword("monitor pcm-tracer profile", "To create Pulse Code Modulation (PCM) capture profiles, use the monitor pcm-tracer profile command in global configuration mode. To disable the configuration, use the no form of this command. PCM capture profiles are disabled. Global configuration (config) You must create at least one user profile under the channels that need to be traced. You can create the following profile operations:", "monitor pcm-tracer profile profile-number { {no} capture-tdm { [T1 | E1] | {analog-voice-port | bri-voice-port}port | ds0 | channel-numnumber}} no monitor pcm-tracer profile profile-number")
	k["monitor permit-list"] = NewKeyword("monitor permit-list", "To configure a destination port permit list or add to an existing destination port permit list, use the monitor permit-list command in global configuration mode. To delete from or clear an existing destination port permit list, use the no form of this command. Disabled Global configuration To prevent accidental configuration of ports as destinations, you can create a permit list of the ports that are valid for use as destinations. With a destination port permit list configured, you can only configure the ports in the permit list as destinations. When you enter multiple instances of interface interface-type slot/port-fastport , you must enter a space before and after the comma. For example, interface interface-type slot/port-fastport , interface-type slot/port-fastport , interface-type slot/port-fastport .", "Activate monitoring monitor permit-list no monitor permit-list Activate monitoring on one port monitor permit-list destination interface interface-type slot/port no monitor permit-list destination interface interface-type slot/port Activate monitoring on one range of ports monitor permit-list destination interface interface-type slot/port-last-port no monitor permit-list destination interface interface-type slot/port-last-port Activate monitoring on two or more ranges of ports monitor permit-list destination interface interface-type slot/port-last-port , [port-last-port] no monitor permit-list destination interface interface-type slot/port-last-port , [port-last-port]")
	k["monitor session egress replication-mode"] = NewKeyword("monitor session egress replication-mode", "To switch the egress-span mode from the default mode (either centralized or distributed depending on your Cisco IOS software release), use the monitor session egress replication-mode command in global configuration mode. To return to the default mode, use the no form of the command. Cisco IOS Releases 12.2(33)SXH2a and later releases: Centralized mode Cisco IOS Releases 12.2(33)SXH, SXH1, and SXH2: Distributed mode Global configuration (config) Centralized egress span monitoring redirects traffic to the supervisor engine for egress monitoring. Distributed egress span monitoring is performed in the ingress module. Distributed replication for Switched Port Analyzer (SPAN), Remote SPAN (RSPAN), and Encapsulated RSPAN (ERSPAN) increases the total throughput at the span destination.", "Cisco IOS Release 12.2(33)SXH2a and Later Releases monitor session egress replication-mode centralized no monitor session egress replication-mode centralized Cisco IOS Release 12.2(33)SXH, SXH1, and SXH2 monitor session egress replication-mode distributed no monitor session egress replication-mode distributed")
	k["monitor session type"] = NewKeyword("monitor session type", "To configure a local Switched Port Analyzer (SPAN), RSPAN, or ERSPAN, use the monitor session type command in global configuration mode. To remove one or more source or destination interfaces from the SPAN session, use the no form of this command. This command has no default settings. Global configuration (config) Release 12.2(18)SXE and later releases support ERSPAN with the Supervisor Engine 720, hardware revision 3.2 or higher. Enter the show module version | include WS-SUP720-BASE command to display the hardware revision. ERSPAN traffic is GRE-encapsulated SPAN traffic that can only be processed by an ERSPAN destination session. This command is not supported on Catalyst 6500 series switches that are configured with a Supervisor Engine 2. All ERSPAN source sessions on a switch must use the same source IP address. You enter the origin ip address command to configure the IP address for the ERSPAN source sessions. All ERSPAN destination sessions on a switch must use the same IP address. You enter the ip address command to configure the IP address for the ERSPAN destination sessions. If the ERSPAN destination IP address is not a Supervisor Engine 720 (for example, it is a network sniffer), the traffic arrives with the GRE and RSPAN headers/encapsulation intact. The ERSPAN source session destination IP address, which must be configured on an interface on the destination switch, is the source of traffic that an ERSPAN destination session sends to the destination ports. You configure the same address in both the source and destination sessions with the ip address command. The ERSPAN ID differentiates the ERSPAN traffic arriving at the same destination IP address from different ERSPAN source sessions. The local ERSPAN session limits are as follows: The monitor session type command creates a new ERSPAN session or allows you to enter the ERSPAN session configuration mode. ERSPAN uses separate source and destination sessions. You configure the source and destination sessions on different switches. The ERSPAN session configuration mode prompts are as follows: The table below lists the ERSPAN destination session configuration mode syntaxes. The table below lists the ERSPAN source session configuration mode syntaxes. When you configure the monitor sessions, follow these syntax guidelines: When you clear the monitor sessions, follow these syntax guidelines: Use the monitor session type local command to configure ingress, egress, or both ingress and egress SPAN sessions. Use the monitor session type local-tx command to configure egress-only SPAN sessions. When you enter the local or the local egress-only SPAN session configuration mode, the prompt changes accordingly to Router(config-mon-local)# or Router(config-mon-local-tx)#, and the following commands are available: The description can be up to 240 characters and cannot contain special characters or spaces. The local SPAN session limits are as follows: If you enter the filter keyword on a monitored trunk interface, only traffic on the set of specified VLANs is monitored. Only one destination per SPAN session is supported. If you attempt to add another destination interface to a session that already has a destination interface configured, you get an error. You must first remove a SPAN destination interface before changing the SPAN destination to a different interface. You can configure up to 64 SPAN destination interfaces, but you can have one egress SPAN source interface and up to 128 ingress source interfaces only. A SPAN session can either monitor VLANs or monitor individual interfaces, but it cannot monitor both specific interfaces and specific VLANs. Configuring a SPAN session with a source interface and then trying to add a source VLAN to the same SPAN session causes an error. Configuring a SPAN session with a source VLAN and then trying to add a source interface to that session also causes an error. You must first clear any sources for a SPAN session before switching to another type of source. Port channel interfaces display in the list of interface options if you have them configured. VLAN interfaces are not supported. However, you can span a particular VLAN by entering the monitor session session source vlan vlan-id command. When you configure the destination , use these guidelines: When you clear the monitor sessions, follow these syntax guidelines:", "monitor session span-session-number type {erspan-destination | erspan-source | local | local-tx | rspan-destination | rspan-source} no monitor session span-session-number type {erspan-destination | erspan-source | local | local-tx | rspan-destination | rspan-source}")
	k["mop device-code"] = NewKeyword("mop device-code", "To identify the type of device sending Maintenance Operation Protocol (MOP) System Identification (sysid) messages and request program messages, use the mop device-code command in global configuration mode. To set the identity to the default value, use the no form of this command. Cisco device code Global configuration The sysid messages and request program messages use the identity information indicated by this command.", "mop device-code commandmop device-code {cisco | ds200} no mop device-code {cisco | ds200}")
	k["mop retransmit-timer"] = NewKeyword("mop retransmit-timer", "To configure the length of time that the Cisco IOS software waits before resending boot requests to a Maintenance Operation Protocol (MOP) server, use the mop retransmit-timer command in global configuration mode. To reinstate the default value, use the no form of this command. 4 seconds Global configuration By default, when the software sends a request that requires a response from a MOP boot server and the server does not respond, the message is re-sent after 4 seconds. If the MOP boot server and router are separated by a slow serial link, it might take longer than 4 seconds for the software to receive a response to its message. Therefore, you might want to configure the software to wait longer than 4 seconds before resending the message if you are using such a link.", "mop retransmit-timer seconds no mop retransmit-timer")
	k["mop retries"] = NewKeyword("mop retries", "To configure the number of times the Cisco IOS software will resend boot requests to a Maintenance Operation Protocol (MOP) server, use the mop retries command in global configuration mode. To reinstate the default value, use the no form of this command. 8 times Global configuration", "mop retries count no mop retries")
	k["motd-banner"] = NewKeyword("motd-banner", "To enable the display of message-of-the-day (MOTD) banners on the specified line or lines, use the motd-banner command in line configuration mode. To suppress the MOTD banners on the specified line or lines, use the no form of this command. This command has no arguments or keywords. Enabled on all lines. Line configuration This command determines whether the router will display the MOTD banner when an EXEC session is created on the specified line or lines. The MOTD banner is defined with the banner motd global configuration command. By default, the MOTD banner is enabled on all lines. Disable the MOTD banner on specific lines using the no motd-banner line configuration command. The MOTD banners can also be disabled by the no exec-banner line configuration command, which disables both MOTD banners and EXEC banners on a line. If the no exec-banner command is configured on a line, the MOTD banner will be disabled regardless of whether the motd-banner command is enabled or disabled. The table below summarizes the effects of the exec-banner command and the motd-banner command. For reverse Telnet connections, the EXEC banner is never displayed. Instead, the incoming banner is displayed. The MOTD banner is displayed by default, but it is disabled if either the no exec-banner command or no motd-banner command is configured. The table below summarizes the effects of the exec-banner command and the motd-banner command for reverse Telnet connections.", "motd-banner no motd-banner")
	k["nmsp enable"] = NewKeyword("nmsp enable", "To enable Network Mobility Service Protocol (NMSP) features on the device, use the nmsp enable command in global configuration mode. To disable, use the no form of this command. This command has no arguments or keywords. NMSP features are not enabled. Configuring the nmsp enable command enables NMSP features on the switch. However, configuring the nmsp stong-cipher command before enabling the NMSP features ensures that all NMSP connections use strong ciphers.", "nmsp enable no nmsp enable")
	k["nmsp strong-cipher"] = NewKeyword("nmsp strong-cipher", "To enable the new ciphers, use the nmsp strong-cipher command in global configuration mode. To disable, use the no form of this command. This command has no arguments or keywords. The new ciphers are not enabled.", "nmsp strong-cipher no nmsp strong-cipher")
	k["no menu"] = NewKeyword("no menu", "To delete a user menu from the configuration file, use the no menu command in global configuration mode. No default behavior or values. Global configuration Use this command to remove any menu commands for a particular menu from the configuration file. As with all global configuration commands, this command will only effect the startup configuration file when you save the running configuration using the copy running-config startup-config EXEC command.", "no menu menu-name")
	k["notify"] = NewKeyword("notify", "To enable terminal notification about pending output from other Telnet connections, use the notify command in line configuration mode. To disable notifications, use the no form of this command. This command has no arguments or keywords. Disabled Line configuration This command sets a line to inform a user that has multiple, concurrent Telnet connections when output is pending on a connection other than the current one.", "notify no notify")
	k["notify syslog"] = NewKeyword("notify syslog", "To enable the sending of notifications of configuration changes to a remote system message logging (syslog), use the notify syslog command in configuration change logger configuration mode. To disable the sending of notifications of configuration changes to the syslog, use the form of this command. Notifications are not sent to the syslog. Configuration change logger configuration (config-archive-log-config) Enable the notify syslog command if you use the syslog to monitor your device. Syslog monitoring prevents the need to gather configuration log information manually.", "notify syslog [contenttype {plaintext | xml}] no notify syslog [contenttype {plaintext | xml}]")
	k["padding"] = NewKeyword("padding", "To set the padding on a specific output character, use the padding command in line configuration mode. To remove padding for the specified output character, use the no form of this command. No padding Line configuration Use this command when the attached device is an old terminal that requires padding after certain characters (such as ones that scrolled or moved the carriage). See the “ASCII Character Set and Hex Values” appendix for a list of ASCII characters.", "padding ascii-number count no padding ascii-number")
	k["parity"] = NewKeyword("parity", "To define generation of a parity bit, use the parity command in line configuration mode. To specify no parity, use the no form of this command. No parity. Line configuration Communication protocols provided by devices such as terminals and modems sometimes require a specific parity bit setting. Refer to the documentation for your device to determine required parity settings. If you use this command to set parity on Cisco AS5350 and Cisco AS5400 NextPort lines, do not also set parity by means of S-register settings in a modemcap. (A modemcap is a series of parameter settings that are sent to your modem to configure it to interact with a Cisco device in a specified way. Cisco IOS software defines modemcaps that have been found to properly initialize most modems so that they function properly with Cisco routers and access servers.)", "parity {none | even | odd | space | mark} no parity")
	k["parser cache"] = NewKeyword("parser cache", "To reenable the Cisco software parser cache after disabling it, use the parser cache command in global configuration mode. To disable the parser cache, use the no form of this command. This command has no arguments or keywords. Parser cache is enabled by default. Global configuration (config) The Parser Cache feature optimizes the parsing (translation and execution) of Cisco software configuration command lines by remembering how to parse recently encountered command lines, decreasing the time required to process large configuration files. The parser cache is enabled by default. However, if you wish to disable the parser cache, you may do so using the no parser cache command in global configuration mode. To reenable the parser cache after it has been disabled, use the parser cache command. When the no parser cache is issued, the command line appears in the running configuration file. However, if the parser cache is reenabled, no command line appears in the running configuration file.", "parser cache no parser cache")
	k["parser command serializer"] = NewKeyword("parser command serializer", "To enable configuration access only to the users holding a configuration lock and to prevent other clients from accessing the running configuration, use the parser command serializer command in global configuration mode. To disable this configuration, use the no form of this command. This command has no arguments or keywords. Access is granted only to the user holding the lock. Global configuration (config) The Parser Concurrency and Locking Improvements feature ensures that exclusive access is granted only to a requested process and prevents other users from concurrently accessing the Cisco IOS configuration. That is, it prevents simultaneous execution of two or more commands. Use the parser command serializer command to configure the Parser Concurrency and Locking Improvements feature.", "parser command serializer no parser command serializer")
	k["parser config cache interface"] = NewKeyword("parser config cache interface", "To reduce the time required for the command-line interpreter to execute commands that manage the running system configuration files, use the parser config cache interface command in global configuration mode. To disable the reduced command execution time functionality, use the no form of this command. This command has no arguments or keywords. Disabled Global configuration (config) Enable the parser config cache interface command to reduce the execution time required for running configuration management commands such as the show running-configuration , write terminal , and copy system:running-configuration commands. Information for these configuration management commands is supplied by nonvolatile generation (NVGEN) processes that query the system for configuration details. The parser config cache interface command is especially useful for managing large system configurations that contain numerous interface configurations. Once enabled, the command provides faster execution of the NVGEN commands that process the running system configuration by caching interface configurations in system memory, and by retrieving only configuration information that has changed. For this reason, the device on which this command is enabled must have enough memory available to store the interface configuration. For example, if the interface configurations take up 15 KB of memory, using this command would require having an additional 15 KB of memory space available. The first time you display the configuration file, you will not see much evidence of improvement in performance because the interface cache will be filled up. However, you will notice performance improvements when you enter subsequent NVGEN-type commands such as the show running-configuration EXEC command. Each time the interface configuration is changed, the interface cache is flushed. Entering an NVGEN-type command after modifying the interface configuration will once again not show any performance improvement until the next NVGEN-type command is entered.", "parser config cache interface no parser config cache interface")
	k["parser config partition"] = NewKeyword("parser config partition", "To enable configuration partitioning, use the parser config partition command. To disable the partitioning of the running configuration, use the no form of this command. No arguments or keywords. This command is enabled by default. Global configuration (config) This command controls (enables or disables) the Configuration Partitioning feature. To display the list of commands that make up the current running configuration for a specific part (“partition”) of the system’s global running configuration, use the show running-config partition command in privileged Exec mode. The Configuration Partitioning feature uses a small amount of system resources. The no parser config partition command allows you to disable this feature if the feature is not needed on your system.", "parser config partition no parser config partition")
	k["partition"] = NewKeyword("partition", "To separate Flash memory into partitions on Class B file system platforms, use the partition command in global configuration mode. To undo partitioning and to restore Flash memory to one partition, use the no form of this command. Flash memory consists of one partition. If the partition size is not specified, partitions of equal size are created. Global configuration For the Cisco 1600 series and Cisco 3600 series routers, to undo partitioning, use the partition flash-filesystem :1 or no partition flash-filesystem : command. For other Class B platforms, use either the partition flash 1 or no partition flash command. If there are files in a partition other than the first, you must use the erase flash-filesystem:partition-number command to erase the partition before reverting to a single partition. When creating two partitions, you must not truncate a file or cause a file to spill over into the second partition.", "Cisco 1600 Series and Cisco 3600 Series Routers partition flash-filesystem: [number-of-partitions] [partition-size] no partition flash-filesystem: All Other Class B Platforms partition flash partitions [size1 size2] no partition flash")
	k["path (archive configuration)"] = NewKeyword("path (archive configuration)", "To specify the location and filename prefix for the files in the Cisco configuration archive, use the path command in archive configuration mode. To disable this function, use the no form of this command. If this command is not configured, no location or filename prefix is specified for files in the Cisco configuration archive. Archive configuration (config-archive) When this command is entered, an archive file of the running configuration is saved when the archive config , write-memory , or copy running-config startup-config command is entered. URLs are commonly used to specify files or location on the World Wide Web. On Cisco devices, URLs can be used to specify the location of a file or directory on a device or a remote file server. The path command uses a URL to specify the location and filename prefix for the Cisco configuration archive. The locations or file systems that you can specify in the url argument are as follows: The colon is required in the location format. The filename of the first archive file is the filename specified in the url argument followed by -1. The filename of the second archive file is the filename specified in the url argument followed by -2 and so on. Because some file systems are incapable of storing the date and time that a file was written, the filename of the archive file can contain the date, time, and device hostname. To include the device hostname in the archive file filename, enter the characters $h (for example, disk0:$h). To include the date and time in the archive file filename, enter the characters $t. When a configuration archive operation is attempted on a local file system, the file system is tested to determine if it is writable and if it has sufficient space to save an archive file. If the file system is read-only or if there is not enough space to save an archive file, an error message is displayed. If you specify the tftp: file server as the location with the path command, you need to create the configuration file on the TFTP file server and change the file’s privileges before the archive config command works properly.", "path url no path url")
	k["periodic"] = NewKeyword("periodic", "To specify a recurring (weekly) time range for functions that support the time-range feature, use the periodic command in time-range configuration mode. To remove the time limitation, use the no form of this command. No recurring time range is defined. Time-range configuration (config-time-range) For Cisco IOS Release 12.2(11)T, IP and Internetwork Packet Exchange (IPX) extended access lists are the only functions that can use time ranges. For further information on using these functions, refer to the Cisco IOS IP Configuration Guide and the Cisco IOS AppleTalk and Novell IPX Configuration Guide. The periodic command is one way to specify when a time range is in effect. Another way is to specify an absolute time period with the absolute command. Use either of these commands after the time-range global configuration command, which specifies the name of the time range. Multiple periodic entries are allowed per time-range command. If the end days-of-the-week value is the same as the start value, they can be omitted. If a time-range command has both absolute and periodic values specified, then the periodic items are evaluated only after the absolute start time is reached, and are not further evaluated after the absolute end time is reached. The table below lists some typical settings for your convenience:", "periodic days-of-the-week hh:mm to [days-of-the-week] hh:mm no periodic days-of-the-week hh:mm to [days-of-the-week] hh:mm")
	k["platform qfp drops threshold"] = NewKeyword("platform qfp drops threshold", "To configure the warning thresholds for per drop cause and/or total QFP drop in packets per second, use the platform qfp drops threshold command. No default behaviour or values.Use the platform qfp drops threshold command to configure the warning thresholds for per drop cause and/or total QFP drop in packets per second.", "platform qfp drops threshold { per-cause | | drop_id | | threshold_value | total threshold_value }")
	k["platform shell"] = NewKeyword("platform shell", "To grant shell access and enter shell access grant configuration mode, use the platform shell command in global configuration mode. To disable this function, use the no form of this command. This command has no arguments or keywords. This command is disabled. Global configuration (config) This command should be entered before using the request platform software system shell command.", "platform shell no platform shell")
	k["power enable"] = NewKeyword("power enable", "To turn on power for the modules, use the power enable command in global configuration mode. To power down a module, use the no form of this command. Enabled Global configuration When you enter the no power enable module slot command to power down a module, the module’s configuration is not saved. When you enter the no power enable module slot command to power down an empty slot, the configuration is saved. The slot argument designates the module number. Valid values for slot depend on the chassis that is used. For example, if you have a 13-slot chassis, valid values for the module number are from 1 to 13.", "power enable module slot no power enable module slot")
	k["power redundancy-mode"] = NewKeyword("power redundancy-mode", "To set the power-supply redundancy mode, use the power redundancy-mode command in global configuration mode. redundant Global configuration", "power redundancy-mode {combined | redundant}")
	k["printer"] = NewKeyword("printer", "To configure a printer and assign a server tty line (or lines) to it, use the printer command in global configuration mode. To disable printing on a tty line, use the no form of this command. No printers are defined. Global configuration (config) This command enables you to configure a printer for operations and assign either a single tty line or a group of tty lines to it. To make multiple printers available through the same printer name, specify the number of a rotary group. In addition to configuring the printer with the printer command, you must modify the file /etc/printcap on your UNIX system to include the definition of the remote printer in the Cisco IOS software. Refer to the Cisco IOS Configuration Fundamentals Configuration Guide for additional information. Use the optional newline-convert keyword in UNIX environments that cannot handle single-character line terminators. This converts newline characters to a carriage-return, linefeed sequence. Use the formfeed keyword when using the line printer daemon (lpd) protocol to print and your system is unable to separate individual output jobs with a form feed (page eject). You can enter the newline-convert and formfeed keywords together and in any order.", "printer printer-name {line number | rotary number} [formfeed] [jobtimeout seconds] [newline-convert] [jobtypes type] no printer printer-name")
	k["private"] = NewKeyword("private", "To save user EXEC command changes between terminal sessions, use the private command in line configuration mode. To restore the default condition, use the no form of this command. This command has no arguments or keywords. User-set configuration options are cleared with the exit EXEC command or when the interval set with the exec-timeout line configuration command has passed. Line configuration This command ensures that the terminal parameters set by the user remain in effect between terminal sessions. This behavior is desirable for terminals in private offices.", "private no private")
	k["process cpu statistics limit entry-percentage"] = NewKeyword("process cpu statistics limit entry-percentage", "To set the process entry limit and the size of the history table for CPU utilization statistics, use the process cpu statistics limit entry-percentage command in global configuration mode. To disable CPU utilization statistics, use the no form of this command. size seconds : 600 seconds Global configuration Use the process cpu statistics limit entry-percentage command to set the entry limit and size of CPU utilization statistics.", "process cpu statistics limit entry-percentage number [size seconds] no process cpu statistics limit entry-percentage")
	k["process cpu threshold type"] = NewKeyword("process cpu threshold type", "To set CPU thresholding notification types and values, use the process cpu threshold type command in global configuration mode. To disable CPU thresholding notifications, use the no form of this command. CPU thresholding notifications are disabled. Global configuration This command defines CPU usage thresholds that, when crossed, cause a CPU thresholding notification. When this command is enabled, Cisco IOS software polls the system at the configured interval. Notification occurs in two situations:", "process cpu threshold type {total | process | interrupt} rising percentage interval seconds [falling fall-percentage interval seconds] no process cpu threshold type {total | process | interrupt}")
	k["process-max-time"] = NewKeyword("process-max-time", "To configure the amount of time after which a process should voluntarily yield to another process, use the process-max-time command in global configuration mode. To reset this value to the system default, use the no form of this command. The default maximum process time is 200 milliseconds. Global configuration Lowering the maximum time a process can run is useful in some circumstances to ensure equitable division of CPU time among different tasks. Only use this command if recommended to do so by the Cisco Technical Assistance Center (TAC).", "process-max-time milliseconds no process-max-time milliseconds")
	k["prompt"] = NewKeyword("prompt", "To customiz e the CLI prompt, use the prompt command in global configuration mode. To revert to the default prompt, use the no form of this command. The default prompt is either Router or the name defined with the hostname global configuration command, followed by an angle bracket (\u003E) for user EXEC mode or a pound sign (#) for privileged EXEC mode. Global configuration You can include customized variables when specifying the prompt. All prompt variables are preceded by a percent sign (%). The table below lists the available prompt variables. Issuing the prompt %h command has the same effect as issuing the no prompt command.", "prompt string no prompt [string]")
	k["prompt config"] = NewKeyword("prompt config", "To configure the system’s prompt for configuration mode, use the prompt config command in global configuration mode. To disable the configuration, use the no form of this command. The system's prompt is not configured for configuration mode. Global configuration (config)", "prompt config hostname-length number no prompt [config]")
	k["refuse-message"] = NewKeyword("refuse-message", "To define and enable a line-in-use message, use the refuse-message command in line configuration mode. To disable the message, use the no form of this command. Disabled (no line-in-use message is displayed). Line configuration Follow this command with one or more blank spaces and a delimiting character of your choice. Then enter one or more lines of text, terminating the message with the second occurrence of the delimiting character. You cannot use the delimiting character within the text of the message. When you define a message using this command, the Cisco IOS software performs the following steps:", "refuse-message d message d no refuse-message")
	k["regexp optimize"] = NewKeyword("regexp optimize", "To optimize the compilation of a regular expression access list, use the regexp optimize command in global configuration mode. To disable the configuration, use the no form of this command. This command has no arguments or keywords. The command is enabled by default. Global configuration (config)", "regexp optimize no regexp optimize")
	k["revision"] = NewKeyword("revision", "To set the revision number for the Multiple Spanning Tree (802.1s) (MST) configuration, use the revision command in MST configuration submode. To return to the default settings, use the no form of this command. version is 0 MST configuration (config-mst) Two Cisco 7600 series routers that have the same configuration but different revision numbers are considered to be part of two different regions.", "revision version no revision")
	k["scheduler allocate"] = NewKeyword("scheduler allocate", "To guarantee CPU time for processes, use the scheduler allocate command in global configuration mode. To restore the default, use the no form of this command. Approximately 5 percent of the CPU is available for process tasks. Global configuration This command applies to the Catalyst 6500 series switches, Cisco 7200 series, Cisco 7500 series, and Cisco 7600 series routers. Entering the scheduler allocate command without arguments is the same as entering the no scheduler allocate or the default scheduler allocate command.", "scheduler allocate interrupt-time process-time no scheduler allocate")
	k["scheduler heapcheck enable"] = NewKeyword("scheduler heapcheck enable", "To enable heapcheck processing, use the scheduler heapcheck enable command in global configuration mode. To disable scheduler heapcheck processing, use the no form of this command. This command has no arguments or keywords. The scheduler heapcheck enable command is disabled by default. If no keywords are specified, scheduler heapcheck processing will not be performed. Global configuration (config)", "scheduler heapcheck enable no scheduler heapcheck enable")
	k["scheduler heapcheck poll"] = NewKeyword("scheduler heapcheck poll", "To validate the memory and edisms poll routine, use the scheduler heapcheck poll command in global configuration mode. To disable the memory check and edisms poll routine, use the no form of this command. This command has no arguments or keywords. The scheduler heapcheck poll command is disabled by default. If no keywords are specified, a sanity check is performed on all the memory blocks and memory pools. Global configuration (config)", "scheduler heapcheck poll no scheduler heapcheck poll")
	k["scheduler heapcheck process"] = NewKeyword("scheduler heapcheck process", "To perform a “sanity check” for corruption in memory blocks when a process switch occurs, use the scheduler heapcheck process command in global configuration mode. To disable this feature, use the no form of this command. This command is disabled by default. If no keywords are specified, a sanity check will be performed on all the memory blocks and memory pools. Global configuration (config) When configuring this command, you can choose none or all memory block keywords (fast , io , multibus , pci , processor , and checktype ). Enabling this command has a significant impact on router performance.", "scheduler heapcheck process [memory [fast] [io] [multibus] [pci] [processor] [checktype {all | data | magic | mlite-data | pointer | refcount | lite-chunks}]] no scheduler heapcheck process")
	k["scheduler interrupt mask profile"] = NewKeyword("scheduler interrupt mask profile", "To start interrupt mask profiling for all processes running on the system, use the scheduler interrupt mask profile command in global configuration mode. To stop interrupt mask profiling, use the no form of this command. This command has no arguments or keywords. Interrupt mask profiling is disabled by default. Global configuration This command enables the collection of details regarding the total amount of time a process has masked interrupts since the interrupt mask profiler was enabled.", "scheduler interrupt mask profile no scheduler interrupt mask profile")
	k["scheduler interrupt mask size"] = NewKeyword("scheduler interrupt mask size", "To configure the maximum number of entries that can exist in the interrupt mask buffer, use the scheduler interrupt mask size command in global configuration mode. To reset the maximum number of entries that can exist in the interrupt mask buffer to the default, use the no form of this command. The default buffer size is 50 entries. Global configuration", "scheduler interrupt mask size buffersize no scheduler interrupt mask size")
	k["scheduler interrupt mask time"] = NewKeyword("scheduler interrupt mask time", "To configure the maximum time that a process can run with interrupts masked before another entry is created in the interrupt mask buffer, use the scheduler interrupt mask time command in global configuration mode. To reset the threshold time to the default, use the no form of this command. The default threshold time value is 50 microseconds. Global configuration", "scheduler interrupt mask time threshold-time no scheduler interrupt mask time")
	k["scheduler interval"] = NewKeyword("scheduler interval", "To control the maximum amount of time that can elapse without running system processes, use the scheduler interval command in global configuration mode. To restore the default, use the no form of this command. High-priority operations are allowed to use as much of the CPU as needed. Global configuration The normal operation of the network server allows the switching operations to use as much of the central processor as is required. If the network is running unusually heavy loads that do not allow the processor the time to handle the routing protocols, give priority to the system process scheduler. High-priority operations are allowed to use as much of the CPU as needed. On the Cisco 7200 series and Cisco 7500 series, use the scheduler allocate global configuration command instead of the scheduler interval command.", "scheduler interval milliseconds no scheduler interval")
	k["scheduler isr-watchdog"] = NewKeyword("scheduler isr-watchdog", "To detect if an Interrupt Service Routine (ISR) is suspended or stalled and to schedule and manage a watchdog timeout on an ISR, use the scheduler isr-watchdog command in global configuration mode. To disable the configuration, use the no form of this command. There are no additional keywords or arguments with this command. The default detection time is 2 minutes. Global configuration (config) The timer ISR checks the current context to avoid holding processes accountable for CPU time spent servicing interrupts during the process time slice, and vice versa for interrupt-level code accountability. However, at each timer tick, the timer ISR applies the full 4 milliseconds of CPU time to the current context. As a result, depending on when the timer tick occurs in relation to a context switch, you might see inaccuracies in CPU utilization accounting compared with the actual computation time because some or all of the tick is being applied to the wrong context.", "scheduler isr-watchdog no scheduler isr-watchdog")
	k["scheduler max-sched-time"] = NewKeyword("scheduler max-sched-time", "To configure or change the maximum time, in milliseconds that a scheduler can run without flagging an error or overload of the CPU, use the scheduler max-sched-time command in global configuration mode. To disable this configuration, use the no form of this command. The default time is 2000 ms to signal an overload of the CPU. Global configuration (config) The default behavior of the scheduler max-sched-time command is to stop the process only if it is fatal. A task is defined as fatal if the task gets another watchdog within 12 hours of being assigned the first watchdog, and a handler has been registered.", "scheduler max-sched-time milliseconds no scheduler max-sched-time")
	k["scheduler process-watchdog"] = NewKeyword("scheduler process-watchdog", "To configure the default action of a watchdog timeout for a process using a scheduler, use the scheduler process-watchdog command in global configuration mode. To disable the configuration, use the no form of this command. The default value is normal . Global configuration (config) The watchdog timer sets the interval after which the scheduler assumes a process has been suspended or stalled and needs to be stopped.", "scheduler process-watchdog {hang | normal | reload | terminate} no scheduler process-watchdog")
	k["scheduler timercheck process"] = NewKeyword("scheduler timercheck process", "To configure process-level timer validation on a scheduler, and check the timer tree of the process after every context switch of the process Packet Identification number (PID) is configured, use the scheduler timercheck process command in global configuration mode. To disable this configuration, use the no form of this command. The process-level timer validation is not configured on a scheduler. Global configuration (config) Specify the show processes timercheck command after configuring the schedule timercheck process command to display the details of the configuration.", "scheduler timercheck process pid no scheduler timercheck process pid")
	k["scheduler timercheck system context"] = NewKeyword("scheduler timercheck system context", "To configure system-level validation on context switches on a scheduler, and check system level-timers, use the scheduler timercheck system context command in global configuration mode. To disable the configuration, use the no form of this command. This command has no additional keywords or arguments. The system-level validation on context switches on a scheduler is not configured. Global configuration (config)", "scheduler timercheck system context no scheduler timercheck system context")
	k["service compress-config"] = NewKeyword("service compress-config", "To compress startup configuration files, use the service compress-config command in global configuration mode. To disable compression, use the no form of this command. This command has no arguments or keywords. Disabled Global configuration After you configure the service compress-config command, the router will compress configuration files every time you save a configuration to the startup configuration. For example, when you enter the copy system:running-config nvram:startup-config command, the running configuration will be compressed before storage in NVRAM. If the file compression succeeds, the following message is displayed: If the boot ROMs do not recognize a compressed configuration, the following message is displayed: If the file compression fails, the following message is displayed: One way to determine whether a configuration file will be compressed enough to fit into NVRAM is to use a text editor to enter the configuration, then use the UNIX compress command to check the compressed size. To get a closer approximation of the compression ratio, use the UNIX compress -b12 command. Once the configuration file has been compressed, the router functions normally. At boot time, the system recognizes that the configuration file is compressed, uncompresses it, and proceeds normally. A partition nvram:startup-config command uncompresses the configuration before displaying it. To disable compression of the configuration file, enter configuration mode and specify the no service compress-config command. Then, exit global configuration mode and enter the copy system:running-config nvram:startup-config command. The router displays an OK message if it is able to write the uncompressed configuration to NVRAM. Otherwise, the router displays an error message indicating that the configuration is too large to store. If the configuration file is larger than the physical NVRAM, the following message is displayed: When the file is truncated, commands at the end of the file are erased. Therefore, you will lose part of your configuration. To truncate and save the configuration, type Y . To not truncate and not save the configuration, type N .", "service compress-config no service compress-config")
	k["service config"] = NewKeyword("service config", "To enable autoloading of configuration files from a network server, use the service config command in global configuration mode. To restore the default, use the no form of this command. This command has no arguments or keywords. Autoloading of configuration files from a network server is disabled, except on systems without NVRAM or with invalid or incomplete information in NVRAM. In these cases, autoloading of configuration files from a network server is enabled automatically. Global configuration (config) Usually, the service config command is used in conjunction with the boot host or boot network command. You must enter the service config command to enable the router to automatically configure the system from the file specified by the boot host or boot network command. With Cisco IOS software Releases 12.3(2)T, 12.3(1)B, and later releases, you no longer have to specify the service config command for the boot host or boot network command to be active. If you specify both the no service config command and the boot host command, the router attempts to find the specified host configuration file. The service config command can also be used without the boot host or boot network command. If you do not specify host or network configuration filenames, the router uses the default configuration files. The default network configuration file is network-confg. The default host configuration file is host-confg, where host is the hostname of the router. If the Cisco IOS software cannot resolve its hostname, the default host configuration file is router-confg.", "service config no service config")
	k["service counters max age"] = NewKeyword("service counters max age", "To set the time interval for retrieving statistics, use the service counters max age command in global configuration mode. To return to the default settings, use the no form of this command. By default, seconds is 0 seconds. Global configuration (config) A fully loaded Catalyst 6500 series switch chassis that is running Cisco IOS software version 12.2(18)SXF or its minor variants (SXF through SXF5) takes 1 to 2 minutes to update the SNMP counters maintained under ifTable and ifXTable. To understand the amount of traffic that a specific port/interface handles, the ifTable/ifXTable is polled. The typical polling interval to meet this is 3 to 5 minutes. There is no advantage if you reduce the polling interval to less than 3 minutes.", "service counters max age seconds no service counters max age")
	k["service decimal-tty"] = NewKeyword("service decimal-tty", "To specify that line numbers be displayed and interpreted as octal numbers rather than decimal numbers, use the no service decimal-tty command in global configuration mode. To restore the default, use the service decimal-tty command. This command has no arguments or keywords. Enabled (line numbers displayed as decimal numbers) Global configuration", "service decimal-tty no service decimal-tty")
	k["service exec-wait"] = NewKeyword("service exec-wait", "To delay the startup of the EXEC on noisy lines, use the service exec-wait command in global configuration mode. To disable the delay function, use the no form of this command. This command has no arguments or keywords. Disabled Global configuration This command delays startup of the EXEC until the line has been idle (no traffic seen) for 3 seconds. The default is to enable the line immediately on modem activation. This command is useful on noisy modem lines or when a modem attached to the line is configured to ignore MNP/V.42 negotiations, and MNP/V.42 modems may be dialing in. In these cases, noise or MNP/V.42 packets may be interpreted as usernames and passwords, causing authentication failure before the user has a chance to type a username or password. The command is not useful on nonmodem lines or lines without some kind of login configured.", "service exec-wait no service exec-wait")
	k["service hide-telnet-address"] = NewKeyword("service hide-telnet-address", "To hide addresses while trying to establish a Telnet session, use the service hide-telnet-address command in global configuration mode. To disable this service, use the no form of this command. This command has no arguments or keywords. Addresses are displayed. Global configuration When you attempt to connect to a device, the router displays addresses and other messages (for example, “Trying router1 (171.69.1.154, 2008)...).” With the hide feature, the router suppresses the display of the address (for example, “Trying router1 address #1...”). The router continues to display all other messages that would normally be displayed during a connection attempt, such as detailed error messages if the connection was not successful. The hide feature improves the functionality of the busy-message feature. When you configure only the busy-message command, the normal messages generated during a connection attempt are not displayed; only the busy-message is displayed. When you use the hide and busy features together you can customize the information displayed during Telnet connection attempts. When you configure the service hide-telnet-address command and the busy-message command, the router suppresses the address and displays the message specified with the busy-message command if the connection attempt is not successful.", "service hide-telnet-address no service hide-telnet-address")
	k["service linenumber"] = NewKeyword("service linenumber", "To configure the Cisco IOS software to display line number information after the EXEC or incoming banner, use the service linenumber command in global configuration mode. To disable this function, use the no form of this command. This command has no arguments or keywords. Disabled Global configuration With the service linenumber command, you can have the Cisco IOS software display the host name, line number, and location each time an EXEC process is started, or an incoming connection is made. The line number banner appears immediately after the EXEC banner or incoming banner. This feature is useful for tracking problems with modems, because the host and line for the modem connection are listed. Modem type information can also be included.", "service linenumber no service linenumber")
	k["service nagle"] = NewKeyword("service nagle", "To enable the Nagle congestion control algorithm, use the service nagle command in global configuration mode. To disable the algorithm, use the no form of this command. This command has no arguments or keywords. Disabled Global configuration When using a standard TCP implementation to send keystrokes between machines, TCP tends to send one packet for each keystroke typed. On larger networks, many small packets use up bandwidth and contribute to congestion. The algorithm developed by John Nagle (RFC 896) helps alleviate the small-packet problem in TCP. In general, it works this way: The first character typed after connection establishment is sent in a single packet, but TCP holds any additional characters typed until the receiver acknowledges the previous packet. Then the second, larger packet is sent, and additional typed characters are saved until the acknowledgment comes back. The effect is to accumulate characters into larger chunks, and pace them out to the network at a rate matching the round-trip time of the given connection. This method is usually effective for all TCP-based traffic. However, do not use the service nagle command if you have XRemote users on X Window system sessions.", "service nagle no service nagle")
	k["service prompt config"] = NewKeyword("service prompt config", "To display the configuration prompt (config), use the service prompt config command in global configuration mode. To remove the configuration prompt, use the no form of this command. This command has no arguments or keywords. The configuration prompts appear in all configuration modes. Global configuration", "service prompt config no service prompt config")
	k["service sequence-numbers"] = NewKeyword("service sequence-numbers", "To enable visible sequence numbering of system logging messages, use the service sequence-numbers command in global configuration mode. To disable visible sequence numbering of logging messages, use the no form of this command. This command has no arguments or keywords. Disabled. Global configuration Each system status messages logged in the system logging process have a sequence reference number applied. This command makes that number visible by displaying it with the message. The sequence number is displayed as the first part of the system status message. See the description of the logging commands for information on displaying logging messages.", "service sequence-numbers no service sequence-numbers")
	k["service slave-log"] = NewKeyword("service slave-log", "To allow secondary Versatile Interface Processor (VIP) cards to log important error messages to the console, use the service slave-log command in global configuration mode . To disable secondary logging, use the no form of this command. This command has no arguments or keywords. This command is enabled by default. Global configuration This command allows secondary slots to log error messages of level 2 or higher (critical, alerts, and emergencies).", "service slave-log no service slave-log")
	k["service tcp-keepalives-in"] = NewKeyword("service tcp-keepalives-in", "To generate keepalive packets on idle incoming network connections (initiated by the remote host), use the service tcp-keepalives-in command in global configuration mode . To disable the keepalives, use the no form of this command. This command has no arguments or keywords. Disabled Global configuration", "service tcp-keepalives-in no service tcp-keepalives-in")
	k["service tcp-keepalives-out"] = NewKeyword("service tcp-keepalives-out", "To generate keepalive packets on idle outgoing network connections (initiated by a user), use the service tcp-keepalives-out command in global configuration mode . To disable the keepalives, use the no form of this command. This command has no arguments or keywords. Disabled Global configuration", "service tcp-keepalives-out no service tcp-keepalives-out")
	k["service tcp-small-servers"] = NewKeyword("service tcp-small-servers", "To enable small TCP servers such as the Echo, use the service tcp-small-servers command in global configuration mode. To disable the TCP server, use the no form of this command. TCP small servers are disabled. Global configuration (config) To use the service tcp-small-servers command, you must be in a user group associated with a task group that includes the proper task IDs. If you suspect user group assignment is preventing you from using a command, contact your Authentication, Authorization, and Accounting (AAA) administrator for assistance. The TCP small servers consist of three services: Discard (port 9), Echo (port 7), and Chargen (port 19). These services are used to test the TCP transport functionality. The discard server receives data and discards it. The echo server receives data and echoes the same data to the sending host. The chargen server generates a sequence of data and sends it to the remote host.", "service tcp-small-servers [max-servers number | no-limit] no service tcp-small-servers [max-servers number | no-limit]")
	k["service telnet-zeroidle"] = NewKeyword("service telnet-zeroidle", "To set the TCP window to zero (0) when the Telnet connection is idle, use the service telnet-zeroidle command in global configuration mode. To disable this service, use the no form of this command. This command has no arguments or keywords. The TCP window is not set to zero when the the Telnet connection is idle. Global configuration (config) Normally, data sent to noncurrent Telnet connections is accepted and discarded. When the service telnet-zero-idle command is enabled, if a session is suspended (that is, some other connection is made active or the router is in the privileged EXEC mode), the TCP window is set to zero. This action prevents the remote host from sending any more data until the connection is resumed. Use this command when it is important that all messages sent by the host be seen by the users and the users are likely to use multiple sessions. Do not use this command if your host will eventually time out and log out a TCP user whose window is zero.", "service telnet-zero-idle no service telnet-zeroidle")
	k["service timestamps"] = NewKeyword("service timestamps", "To configure the system to apply a time stamp to debugging messages or system logging messages, use the service timestamps command in global configuration mode . To disable this service, use the no form of this command. Time stamps are applied to debug and logging messages. Global configuration (config) Time stamps can be added to either debugging messages (service timestamp debug ) or logging messages (service timestamp log ) independently. If the service timestamps command is specified with no arguments or keywords, the default is service timestamps debug uptime . The no service timestamps command by itself disables time stamps for both debug and log messages. The uptime form of the command adds time stamps (such as “2w3d”) that indicating the time since the system was rebooted. The datetime form of the command adds time stamps (such as “Sep 5 2002 07:28:20”) that indicate the date and time according to the system clock. Entering the service timestamps {debug | log } command a second time will overwrite any previously configured service timestamp {debug | log } commands and associated options. To set the local time zone, use the clock timezone zonehours-offset command in global configuration mode. The time stamp will be preceeded by an asterisk or period if the time is potentially inaccurate. The table below describes the symbols that proceed the time stamp.", "service timestamps [debug | log] [uptime | datetime [msec]] [localtime] [show-timezone] [year] no service timestamps [debug | log]")
	k["service udp-small-servers"] = NewKeyword("service udp-small-servers", "To enable small User Datagram Protocol (UDP) servers such as the Echo, use the service udp-small-servers command in global configuration mode. To disable the UDP server, use the no form of this command. UDP small servers are disabled. Global configuration (config) To use this command, you must be in a user group associated with a task group that includes the proper task IDs. If you suspect user group assignment is preventing you from using a command, contact your Authentication, Authorization, and Accounting (AAA) administrator for assistance. The UDP small servers currently consist of three services: Discard (port 9), Echo (port 7), and Chargen (port 19). These services are used to test the UDP transport functionality. The discard server receives data and discards it. The echo server receives data and echoes the same data to the sending host. The chargen server generates a sequence of data and sends it to the remote host.", "service udp-small-servers [max-servers number | no-limit] no service udp-small-servers [max-servers number | no-limit]")
	k["service-module apa traffic-management"] = NewKeyword("service-module apa traffic-management", "To configure traffic management on the router, use the service-module apa traffic-management command in interface configuration mode. None Interface configuration mode To perform traffic management, you enable or disable the flow of packets by configuring the service module interface and the router interface. Two traffic management options are available:", "service-module apa traffic-management [monitor | inline]")
	k["show"] = NewKeyword("show", "To verify the Multiple Spanning Tree (MST) configuration, use the show command in MST configuration mode. This command has no default settings. MST configuration (config-mst) The display output from the show pending command is the edited configuration that will replace the current configuration if you enter the exit command to exit MST configuration mode. Entering the show command with no arguments displays the pending configurations.", "show [current | pending]")
	k["show declassify"] = NewKeyword("show declassify", "To display the state of the declassify function (enabled, in progress, and so forth) and the sequence of declassification steps that will be performed, use the show declassify command in global configuration mode. This command has no arguments or keywords. Global configuration", "show declassify")
	k["slave auto-sync config"] = NewKeyword("slave auto-sync config", "To turn on automatic synchronization of configuration files for a Cisco 7507 or Cisco 7513 router that is configured for High System Availability (HSA) using Dual RSP Cards, use the slave auto-sync config global configuration command. To turn off automatic synchronization, use the no form of the command. This command has no arguments or keywords. Enabled Global configuration Use this command for a Cisco 7507 or Cisco 7513 router that is configured for dual RSP cards. On the Cisco 7507 and Cisco 7513 router, you can install two RSP cards in a single router to improve system availability. Dual RSP Cards is a High System Availability (HSA) feature. In automatic synchronization mode, when you issue a copy EXEC command that specifies the primary devices’ startup configuration (nvram:startup-config ) as the target, the primary device also copies the same file to the secondary devices' startup configuration (slavenvram:startup-config ). Use this command when implementing HSA for simple hardware backup or for software error protection to ensure that the primary and secondary RSP contain the same configuration files.", "slave auto-sync config no slave auto-sync config")
	k["slave default-slot"] = NewKeyword("slave default-slot", "To specify the default secondary Route Switch Processor (RSP) card on a Cisco 7507 or Cisco 7513 router, use the slave default-slot global configuration command. The default secondary is the RSP card located in the higher number processor slot. On the Cisco 7507 router, processor slot 3 contains the default secondary RSP. On the Cisco 7513 router, processor slot 7 contains the default secondary RSP. Global configuration Use this command for a Cisco 7507 or Cisco 7513 router that is configured for Dual RSP Cards. On the Cisco 7507 and Cisco 7513 router, you can install two RSP cards in a single router to improve system availability. Dual RSP Cards is a High System Availability (HSA) feature. The router uses the default secondary information when booting as follows:", "slave default-slot processor-slot-number")
	k["slave image"] = NewKeyword("slave image", "To specify the image that the secondary Route Switch Processor (RSP) runs on a Cisco 7507 or Cisco 7513 router, use the slave image command in global configuration mode. The default is to load the image from the system bundle. Global configuration (config) Use this command for a Cisco 7507 or Cisco 7513 router that is configured for Dual RSP Cards. On the Cisco 7507 and Cisco 7513 router, you can install two RSP cards in a single router to improve system availability. Dual RSP Cards is a High System Availability (HSA) feature. Use the slave image command to override the secondary image that is bundled with the primary image. When using HSA for simple hardware backup, ensure that the secondary image is in the same location on the primary and the secondary RSP card. Thus, if the secondary RSP card becomes the primary RSP card, it will be able to find the secondary image and download it to the new secondary card.", "slave image {system | file-url}")
	k["slave reload"] = NewKeyword("slave reload", "To force a reload of the image that the secondary Route Switch Processor (RSP) card is running on a Cisco 7507 or Cisco 7513 router, use the slave reload global configuration command. This command has no arguments or keywords. No default behavior or values. Global configuration Use this command for a Cisco 7507 or Cisco 7513 router that is configured for Dual RSP Cards. On the Cisco 7507 and Cisco 7513 router, you can install two RSP cards in a single router to improve system availability. Dual RSP Cards is a High System Availability (HSA) feature. After using the slave image global configuration command to specify the image that the secondary RSP runs on a Cisco 7507 or Cisco 7513 router, use the slave reload command to reload the secondary RSP with the new image. The slave reload command can also be used to force the secondary RSP to reboot its existing image.", "slave reload")
	k["slave terminal"] = NewKeyword("slave terminal", "To enable access to the secondary Route Switch Processor (RSP) console, use the slave terminal global configuration command. To disable access to the secondary RSP console, use the no form of this command. This command has no arguments or keywords. Enabled Global configuration The secondary console does not have enable password protection. Thus, an individual connected to the secondary console port can enter privileged EXEC mode and view or erase the configuration of the router. Use the no slave terminal command to disable secondary console access and prevent security problems. When the secondary console is disabled, users cannot enter commands. If secondary console access is disabled, the following message appears periodically on the secondary console:", "slave terminal no slave terminal")
	k["software source list"] = NewKeyword("software source list", "To create a list of input bundles or directories, use the software source list command in global configuration mode. To erase a source list, use the no form of the software source list command. No source list exists. If it happens that using either the software install file command or the software install source commands result in an error due to too many characters on the command line, you can create a list of input bundles or directories using the software source list command. The available configured lists may then be verified using the show running config command, which also displays the contents of the lists. The pool of packages defined by a list can be displayed with the show software source list list-name command.", "software source list list-name-string To erase a source list, use the no form of the software source list command. no software source list list-name-string")
	k["special-character-bits"] = NewKeyword("special-character-bits", "To configure the number of data bits per character for special characters such as software flow control characters and escape characters, use the special-character-bits command in line configuration mode. To restore the default value, use the no form of this command. 7-bit ASCII character set Line configuration Setting the special character bits to 8 allows you to use twice as many special characters as with the 7-bit ASCII character set. The special characters affected by this setting are the escape, hold, stop, start, disconnect, and activation characters.", "special-character-bits {7 | 8} no special-character-bits")
	k["stack-mib portname"] = NewKeyword("stack-mib portname", "To specify a name string for a port, use the stack-mib portname command in interface configuration mode. This command has no default settings. Interface configuration Using the stack-mib command to set a name string to a port corresponds to the portName MIB object in the portTable of CISCO-STACK-MIB. portName is the MIB object in the portTable of CISCO-STACK-MIB. You can set this object to be descriptive text describing the function of the interface.", "stack-mib portname portname")
	k["state-machine"] = NewKeyword("state-machine", "To specify the transition criteria for the state of a particular state machine, use the state-machine command in global configuration mode . To remove a particular state machine from the configuration, use the no form of this command. No transition criteria are specified. Global configuration (config) This command is paired with the dispatch-machine line configuration command, which defines the line on which the state machine is effective.", "state-machine name state first-character last-character [next-state delay | transmit] no state-machine name")
	k["stopbits"] = NewKeyword("stopbits", "To set the number of the stop bits transmitted per byte, use the stopbits command in line configuration mode. To restore the default value, use the no form of this command. 2 stop bits per byte Line configuration Communication protocols provided by devices such as terminals and modems often require a specific stop-bit setting.", "stopbits {1 | 1. 5 | 2} no stopbits")
	k["storm-control level"] = NewKeyword("storm-control level", "To set the suppression level, use the storm-control level command in interface configuration mode. To turn off the suppression mode, use the no form of this command. All packets are passed. Interface configuration You can enter this command on switch ports and router ports. Enter the storm-control level command to enable traffic storm control on the interface, configure the traffic storm-control level, and apply the traffic storm-control level to all traffic storm-control modes that are enabled on the interface. Only one suppression level is shared by all three suppression modes. For example, if you set the broadcast level to 30 and set the multicast level to 40, both levels are enabled and set to 40. The Cisco 7600 series router supports storm control for multicast and unicast traffic only on Gigabit Ethernet LAN ports. The switch supports storm control for broadcast traffic on all LAN ports. The multicast and unicast keywords are supported on Gigabit Ethernet LAN ports only. These keywords are not supported on 10 Mbps, 10/100 Mbps, 100 Mbps, or 10-Gigabit Ethernet modules. The period is required when you enter the fractional-suppression level. The suppression level is entered as a percentage of the total bandwidth. A threshold value of 100 percent means that no limit is placed on traffic. A threshold value of 0 or 0.0 (fractional) percent means that all specified traffic is blocked on a port, with the following guidelines: Enter the show interfaces counters broadcast command to display the discard count. Enter the show running-config command to display the enabled suppression mode and level setting. To turn off suppression for the specified traffic type, you can do one of the following:", "storm-control {broadcast | multicast | unicast} level level [. level] no storm-control {broadcast | multicast | unicast} level")
	k["sync-restart-delay"] = NewKeyword("sync-restart-delay", "To set the synchronization-restart delay timer to ensure accurate status reporting, use the sync-restart-delay command in interface configuration mode. To disable the synchronization-restart delay timer, use the no form of this command. timer is 210 milliseconds. Interface configuration This command is supported on Gigabit Ethernet fiber ports only. The status register records the current status of the link partner.", "sync-restart-delay timer no sync-restart-delay timer")
	k["system flowcontrol bus"] = NewKeyword("system flowcontrol bus", "To set the FIFO overflow error count, use the system flowcontrol bus command in global configuration mode. To return to the original FIFO threshold settings, use the no form of this command. auto Global configuration", "[default] system flowcontrol bus {auto | on} no system flowcontrol bus")
	k["system jumbomtu"] = NewKeyword("system jumbomtu", "To set the maximum size of the Layer 2 and Layer 3 packets, use the system jumbo mtu command in global configuration mode. To revert to the default MTU setting, use the no form of this command. mtu-size is 9216 bytes. Global configuration The mtu-size parameter specifies the Ethernet packet size, not the total Ethernet frame size. The Layer 3 MTU is changed as a result of entering the system jumbo mtu command. The system jumbo mtu command enables the global MTU for port ASICs. On a port ASIC after jumbo frames are enabled, the port ASIC accepts any size packet on the ingress side and checks the outgoing packets on the egress side. The packets on the egress side that exceed the global MTU are dropped by the port ASIC. For example, if you have port A in VLAN 1 and Port B in VLAN 2, and if VLAN 1 and VLAN 2 are configured for mtu 9216 and you enter the system jumbomtu 4000 command, the packets that are larger than 4000 bytes are not transmitted out because Ports B and A drop anything larger than 4000 bytes.", "system jumbomtu mtu-size no system jumbomtu")
	k["tdm clock priority"] = NewKeyword("tdm clock priority", "To configure the clock source and priority of the clock source used by the time-division multiplexing (TDM) bus on the Cisco AS5350, AS5400, and AS5850 access servers, use the tdm clock priority command in global configuration mode. To return the clock source and priority to the default values, use the no form of this command. If no clocks are configured, the system uses a default, primary clock. An external clock is never selected by default; it must be explicitly configured. Global configuration The TDM bus can receive an input clock from one of three sources on the gateway: Trunk-Card Ports The TDM bus can be synchronized with any trunk cards. On the CT1/CE1 trunk card, each port receives the clock from the T1/E1 line. The CT3 trunk card uses an M13 multiplexer to receive the DS1 clock. Each port on each trunk-card slot has a default clock priority. Also, clock priority is configurable through the tdm clock priority command. External Clock The TDM bus can be synchronized with an external clock source that can be used as an additional network reference. If no clocks are configured, the system uses a primary clock through a software-controlled default algorithm. If you want the external T1/E1 clock (from the BITS interface) as the primary clock source, you must configure it using the external keyword with the tdm clock priority command; the external clock is never selected by default. The BITS interface requires a T1 line composite clock reference set at 1.544 MHz and an E1 line composite clock reference set at 2.048 MHz. Free-Running Clock If there is no good clocking source from a trunk card or an external clock source, then select the free-running clock from the internal oscillator using the freerun keyword with the tdm clock priority command.", "tdm clock priority priority-number {slot/ds1-port | slot/ds3-port:ds1-port | external | freerun} no tdm clock priority priority-number {slot/ds1-port | slot/ds3-port:ds1-port | external | freerun}")
	k["terminal-queue entry-retry-interval"] = NewKeyword("terminal-queue entry-retry-interval", "To change the retry interval for a terminal port queue, use the terminal-queue entry-rety-interval command in global configuration mode. To restore the default terminal port queue interval, use the no form of this command. 60 seconds Global configuration If a remote device (such as a printer) is busy, the connection attempt is placed in a terminal port queue. If you want to decrease the waiting period between subsequent connection attempts, decrease the default of 60 to an interval of 10 seconds. Decrease the time between subsequent connection attempts when, for example, a printer queue stalls for long periods.", "terminal-queue entry-retry-interval seconds no terminal-queue entry-retry-interval")
	k["terminal-type"] = NewKeyword("terminal-type", "To specify the type of terminal connected to a line, use the terminal-type command in line configuration mode. To remove any information about the type of terminal and reset the line to the default terminal emulation, use the no form of this command. VT100 Line configuration This command records the type of terminal connected to the line. The terminal-name argument provides a record of the terminal type and allows terminal negotiation of display management by hosts that provide that type of service. For TN3270 applications, this command must follow the corresponding ttycap entry in the configuration file.", "terminal-type {terminal-name | terminal-type} no terminal-type")
	k["tftp-server"] = NewKeyword("tftp-server", "To configure a router or a Flash memory device on the router as a TFTP server, use one of the following tftp-server commands in global configuration mode. This command replaces the tftp-server system command. To remove a previously defined filename, use the no form of this command with the appropriate filename. Disabled Global configuration You can specify multiple filenames by repeating the tftp-server command. The system sends a copy of the system image contained in ROM or one of the system images contained in Flash memory to any client that issues a TFTP Read Request with this filename. If the specified filename1 or filename2 argument exists in Flash memory, a copy of the Flash image is sent. On systems that contain a complete image in ROM, the system sends the ROM image if the specified filename1 or filename2 argument is not found in Flash memory. Images that run from ROM cannot be loaded over the network. Therefore, it does not make sense to use TFTP to offer the ROMs on these images. On the Cisco 7000 family routers, the system sends a copy of the file contained on one of the Flash memory devices to any client that issues a TFTP Read Request with its filename.", "tftp-server flash [partition-number :] filename1 [alias filename2] [access-list-number] tftp-server rom alias filename1 [access-list-number] no tftp-server {flash [partition-number :] filename1 | rom alias filename2} Cisco 1600 Series and Cisco 3600 Series Routers tftp-server flash [device :] [partition-number :] filename no tftp-server flash [device :] [partition-number :] filename Cisco 7000 Family Routers tftp-server flash device : filename no tftp-server flash device : filename")
	k["time-period"] = NewKeyword("time-period", "To set the time increment for automatically saving an archive file of the current running configuration in the Cisco configuration archive, use the time-period command in archive configuration mode. To disable this function, use the no form of this command. No time increment is set. Archive configuration (config-archive) If this command is configured, an archive file of the current running configuration is automatically saved after the given time specified by the minutes argument. Archive files continue to be automatically saved at this given time increment until this function is disabled. Use the maximum command to set the maximum number of archive files of the running configuration to be saved.", "time-period minutes no time-period minutes")
	k["vacant-message"] = NewKeyword("vacant-message", "To display an idle terminal message, use the vacant-message command in line configuration mode. To remove the default vacant message or any other vacant message that may have been set, use the no form of this command. The format of the default vacant message is as follows: This message is generated by the system. Line configuration This command enables the banner to be displayed on the screen of an idle terminal. The vacant-message command without any arguments restores the default message. Follow this command with one or more blank spaces and a delimiting character of your choice. Then enter one or more lines of text, terminating the message with the second occurrence of the delimiting character.", "vacant-message [d message d] no vacant-message")
	k["vtp"] = NewKeyword("vtp", "To configure the global VLAN Trunking Protocol (VTP) state, use the vtp command in global configuration mode. To return to the default value, use the no form of this command. The defaults are as follows: Global configuration (config) Extended-range VLANs are not supported by VTP. When you define the domain-name value , the dom ain name is case sensitive and can be from 1 to 32 characters. The filename and interface-name values are ASCII strings from 1 to 255 characters. You must configure a password on each network device in the management domain when the switch is in secure mode. A VTP version 2-capable network device can operate in the same VTP domain as a network device running VTP version 1 if VTP version 2 is disabled on the VTP version 2-capable network device (VTP version 2 is disabled by default). Do not enable VTP version 2 on a network device unless all of the network devices in the same VTP domain are version 2-capable. When you enable VTP version 2 on a network device, all of the version 2-capable network devices in the domain enable VTP version 2. In a Token Ring environment, you must enable VTP version 2 for VLAN switching to function properly. Enabling or disabling VTP pruning on a VTP server enables or disables VTP pruning for the entire management domain. Configuring VLANs as pruning eligible or pruning ineligible on a Cisco 7600 series router affects pruning eligibility for those VLANs on that switch only; it does not affect pruning eligibility on all network devices in the VTP domain. The vtp password , vtp pruning , and vtp version commands are not placed in startup memory but are included in the VTP transparent-mode startup configuration file. Extended-range VLANs are not supported by VTP. You can configure the pruning keyword in VTP-server mode; the version keyword is configurable in VTP-server mode or VTP transparent mode. The password- value argument is an ASCII string from 8 to 64 characters identifying the administrative domain for the device. VTP pruning causes information about each pruning-eligible VLAN to be removed from VTP updates if there are no stations belonging to that VLAN. All Cisco 7600 series routers in a VTP domain must run the same version of VTP. VTP version 1 and VTP version 2 do not operate on Cisco 7600 series routers in the same VTP domain. If all Cisco 7600 series routers in a domain are VTP version 2-capable, you need only to enable VTP version 2 on one Cisco 7600 series router; the version number is then propagated to the other version 2-capable Cisco 7600 series routers in the VTP domain. If you toggle the version 2 mode, certain default VLAN parameters are modified. If you enter the vtp mode off command, it sets the device to off. If you enter the no vtp mode off command, it resets the device to the VTP server mode. In VTP version 3, the VTP mode has to be specified on a per-feature basis. Use the vlan and mst keywords to configure the VTP mode on VLAN and MST instances. To configure the VTP mode for any other feature, use the unknown keyword. When you convert from either VTP version 1 or 2 to version 3, the current mode configuration will be preserved. With VTP version 3, a new method is available for hiding the VTP password from the configuration file. When you use the hidden keyword, the secret key that is generated from the password string is saved in the const_nvram:vlan.dat file. If you use the secret keyword, you can directly configure the password secret key. By using the secret keyword, you can distribute the password in the secret key format rather than in the cleartext format.", "vtp {domain domain-name | file filename | interface interface-name [only] | mode {client | off | server | transparent} {vlan | mst | unknown} | password password-value [hidden | secret] | pruning | version {1 | 2 | 3}} no vtp")
	k["warm-reboot"] = NewKeyword("warm-reboot", "To enable a router to do a warm-reboot, use the warm-reboot command in global configuration mode. To disable warm rebooting, use the no form of this command. Warm rebooting is disabled. If warm rebooting is enabled, the default value for the count number option is 5 times, and the default value for the uptime minutes option is 5 minutes. Global configuration Use the warm-reboot command to enable the router to reload a Cisco IOS image without ROM monitor mode (ROMMON) intervention, in which the image restores read-write data from a previously saved copy in the RAM and starts execution from that point. Unlike a cold reboot, this process does not involve a flash to RAM copy or self-decompression of the image.", "warm-reboot [count number] [uptime minutes] no warm-reboot count number uptime minutes")
	k["width"] = NewKeyword("width", "To set the terminal screen width, use the width command in line configuration mode. To return to the default screen width, use the no form of this command. 80 character columns Line configuration By default, the route provides a screen display width of 80 characters. You can reset this value for the current session if it does not meet the needs of your terminal. The rlogin protocol uses the value of the characters argument to set up terminal parameters on a remote host.", "width characters no width")

	return k
}

func Completions() []protocol.CompletionItem {
	var c []protocol.CompletionItem
	for _, k := range Keywords() {
		c = append(c, k.Completion())
	}
	return c
}
